cc.Class({
    extends: cc.Component,

    properties: {
        _rtype:2,

        _itemList:[],
        _canClick:false,
        // _jumpItem:[[20,13],[28,6]],
    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    onEnable(){
        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvSubGameAction, this);
    },

    onDisable(){
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvSubGameAction, false, this);
    },

    Init(){
        this._node_map = cc.find("safe_node/node_map", this.node);
        this._node_map.active = false;

        this._spr_road1 = cc.find("node_road/spr_road1", this._node_map);
        this._spr_road2 = cc.find("node_road/spr_road2", this._node_map);
        this._node_road1 = cc.find("node_road/spine_road1", this._node_map);
        this._node_road2 = cc.find("node_road/spine_road2", this._node_map);
        this._node_road1.active = false;
        this._node_road2.active = false;


        for (let i = 1; i <= 38; i++){
            let item = cc.find("node_items/item"+i, this._node_map);
            this._itemList.push(item);
        }

        this._lbl_free_cnt = cc.find("node_freeCnt/lbl", this._node_map);
        this._par_freeCnt = cc.find("node_freeCnt/par", this._node_map);
        this._par_freeCnt.active = false;
        this._node_freeType = cc.find("node_freeType", this._node_map);
        this._par_freeType = cc.find("node_freeType/par", this._node_map);
        this._par_freeType.active = false;
        this._spine_dog = cc.find("node_items/spine_dog", this._node_map);

        this._btn_sz = cc.find("btn_sz", this._node_map);
        this._btn_sz.off("click");
        Global.btnClickEvent(this._btn_sz, this.clickSzBtn, this);
        // this._spr_sz = cc.find("spr", this._btn_sz);
        this._spine_sz = cc.find("spine_sz", this._btn_sz);
        this._sz_tip = cc.find("spine_tip", this._btn_sz);

        this._par_win = cc.find("safe_node/map_par_win", this.node);
        this._par_win.active = false;

        this._btn_entrance = cc.find("btn_entrance", this._node_map);
        this._spine_fei = cc.find("spine_fei_zz", this._node_map);
        this._spine_fei.active = false;

    },

    showMapGame(){
        return new Promise(async(success, failed)=>{
            Global.SlotsSoundMgr.playBgm("map_bgm");

            this._node_map.active = true;

            this._mapGame = cc.vv.gameData.getMapGame();
            this._curStep = this._mapGame.currStep; // 当前小狗位置
            // this._hisStep = this._mapGame.hisSteps;  // 已经踩过的位置
            // this._freeCnt = this._mapGame.freeCnt;  // 免费游戏次数
            // this._wildCols = this._mapGame.wildCols;// wild列数
            // this._slotCnt = this._mapGame.slotCnt;  // slot的数量
            // this._extraRow = this._mapGame.extraRow;// 额外的行数
            // this._winCoin = this._mapGame.winCoin;  // 获得的金币数量
            // this._jumpSteps = this._mapGame.jumpSteps;  // 已跳转的位置(地图中有两个位置可以跳转)


            this.initMapItem();
            this.initRoads();
            this.initDog();
            this.setFreeCnt();
            this.initFreeType();
            this.initWinCoin();
            this.initSzBtn();
            this.updatePawNum();

            cc.vv.gameData.GetBottomScript().SetWin(this._mapGame.winCoin);

            await cc.vv.gameData.awaitTime(1);
            this.setCanClick(true);

            this._mapSuccess = success;
        })
    },

    async endMapGame(){
        Global.SlotsSoundMgr.playEffect("map_end");
        await cc.vv.gameData.awaitTime(0.8);

        cc.vv.gameData.SetTotalFree(this._mapGame.freeCnt);
        cc.vv.gameData.SetFreeTime(this._mapGame.freeCnt);
        cc.vv.gameData.setFreeAddRow(this._mapGame.extraRow);
        cc.vv.gameData.setFreeSlotsCnt(this._mapGame.slotCnt);
        cc.vv.gameData.setFreeWildCols(this._mapGame.wildCols);

        await cc.vv.gameData.getPopupScript().playTriFreeAnim();

        cc.vv.gameData.getPopupScript().playQPAnim1();
        await cc.vv.gameData.awaitTime(0.5);

        // this._node_map.active = false;
        //显示免费次数
        cc.vv.gameData.GetBottomScript().ShowFreeModel(true,0,this._mapGame.freeCnt);
        await cc.vv.gameData.getFreeScript().initShowSlotsData(true);

        if(this._mapSuccess){
            this._node_map.active = false;

            this._mapSuccess();
            this._mapSuccess = null;
        }
    },

    hideMapNode(){
        this._node_map.active = false;
    },

    setCanClick(val){
        this._canClick = val;
    },

    // 初始地图选项
    initMapItem(){
        let hisStep = this._mapGame.hisSteps
        for (let i = 0; i < this._itemList.length; i++){
            this._itemList[i].opacity = 255;

            this._itemList[i].active = !hisStep.includes(i + 1);
            if(cc.find("spr", this._itemList[i])){
                cc.find("spr", this._itemList[i]).active = true;
            }
        }
    },

    // 初始路
    initRoads(){
        let steps = this._mapGame.jumpSteps;
        if(steps.includes(29)){
            this._node_road1.active = true;
            this._node_road1.getComponent(sp.Skeleton).setAnimation(0,"animation2", false);
            this._spr_road1.active = false;
        }else {
            this._node_road1.active = false;
            this._spr_road1.active = true;
        }
        if(steps.includes(21)){
            this._node_road2.active = true;
            this._node_road2.getComponent(sp.Skeleton).setAnimation(0,"animation1", false);
            this._spr_road2.active = false;
        }else {
            this._node_road2.active = false;
            this._spr_road2.active = true;
        }
    },

    // 初始狗的位置和动画
    initDog(){
        this._spine_dog.position = this._itemList[this._curStep-1].position;
        this._spine_dog.getComponent(sp.Skeleton).setAnimation(0,"animation1",true);
    },

    // 初始免费次数
    setFreeCnt(){
        this._lbl_free_cnt.getComponent(cc.Label).string = this._mapGame.freeCnt;
    },

    // 初始免费类型
    initFreeType(){
        this._slotCnt = this._mapGame.slotCnt;
        this._extraRow = this._mapGame.extraRow;
        this._wildCols = this._mapGame.wildCols

        let scaleList = [1, 0.8, 0.6, 0.6];
        // let posList = [[[0,0]], [[0,51],[0,-51]], [[0,51],[-74,-51],[74,51]], [[-74,51],[74,51],[-74,-51],[74,-51]]]
        let pic_row4 = "theme128_map_3";
        let pic_wild4 = "theme128_map_2";
        let pic_row3 = "theme128_map_6";
        let pic_wild3 = "theme128_map_4";
        let map_altas = cc.vv.gameData.GetAtlasByName("map");

        this._node_freeType.setScale(scaleList[this._slotCnt-1]);
        let slotsList = [];
        for (let i = 1; i <= 4; i++){
            let slots = cc.find("slots_"+i, this._node_freeType);
            if(i > this._slotCnt){
                slots.active = false;
            } else {
                slots.active = true;

                let spr_row = cc.find("row", slots);
                spr_row.getComponent(cc.Sprite).spriteFrame = map_altas.getSpriteFrame(this._extraRow?pic_row4:pic_row3);

                for (let j = 1; j <= 5; j++){
                    cc.find("wild_"+j, slots).active = this._wildCols.includes(j);
                    cc.find("wild_"+j, slots).getComponent(cc.Sprite).spriteFrame = map_altas.getSpriteFrame(this._extraRow?pic_wild4:pic_wild3)
                }

                slotsList.push(slots);

                // let width = spr_row.width;
                // let height = spr_row.height;
            }
        }

        let width = cc.find("row", slotsList[0]).width/2
        let height = cc.find("row", slotsList[0]).height/2
        if(slotsList.length == 1){
            slotsList[0].position = cc.v2(0,0);
        } else if(slotsList.length == 2){
            slotsList[0].position = cc.v2(0,height);
            slotsList[1].position = cc.v2(0,-height);
        } else if(slotsList.length == 3){
            slotsList[0].position = cc.v2(0,height);
            slotsList[1].position = cc.v2(-width,-height);
            slotsList[2].position = cc.v2(width,-height);
        } else if(slotsList.length == 4){
            slotsList[0].position = cc.v2(-width,height);
            slotsList[1].position = cc.v2(width,height);
            slotsList[2].position = cc.v2(-width,-height);
            slotsList[3].position = cc.v2(width,-height);
        }
    },

    // 初始赢钱
    initWinCoin(){
        if(this._mapGame.winCoin > 0){
            cc.vv.gameData.GetBottomScript().SetWin(this._mapGame.winCoin);
        }
    },

    // setSzSpr(){
    //     let map_altas = cc.vv.gameData.GetAtlasByName("map");
    //     this._spr_sz.getComponent(cc.Sprite).spriteFrame = map_altas.getSpriteFrame("theme128_map_dice"+this._diceId)
    // },

    // 初始色子
    initSzBtn(){
        this._diceId = 6;
        // this.setSzSpr(this._diceId);
        this._spine_sz.getComponent(sp.Skeleton).setSkin("default");
        this._spine_sz.getComponent(sp.Skeleton).setAnimation(0,"animation",false);
        this._sz_tip.active = false;

        this.playSzIdleAnim(true);
    },

    // 初始爪子数
    updatePawNum(addPaw){
        let pawStore = cc.vv.gameData.getPawStore();
        if(addPaw){
            pawStore.pawCnt += addPaw;
            cc.vv.gameData.setPawStore(pawStore);
            cc.vv.gameData.getStoreScript().updateCurMoney();

            let spine_fz = cc.find("spine_fz", this._btn_entrance);
            spine_fz.getComponent(sp.Skeleton).setAnimation(0,"animation3", false);
            spine_fz.getComponent(sp.Skeleton).addAnimation(0,"animation4", true);
        }

        let lbl_money = cc.find("lbl_money", this._btn_entrance);
        lbl_money.getComponent(cc.Label).string = Global.FormatNumToComma(pawStore.pawCnt);
    },

    // 色子闲置动画
    playSzIdleAnim(bPlay){
    //     this._spr_sz.stopAllActions();
    //     this._spr_sz.angle = 0;
        let self = this;
        if(bPlay){
            cc.tween(this._sz_tip)
                .delay(3)
                .call(()=>{
                    self._sz_tip.active = true;
                    self._sz_tip.getComponent(sp.Skeleton).setAnimation(0,"animation1",false);
                    self._sz_tip.getComponent(sp.Skeleton).addAnimation(0,"animation2",true);
                })
    //             .repeatForever(cc.tween()
    //                 .to(0.2,{angle:12})
    //                 .to(0.2,{angle:-12})
    //                 .to(0.2,{angle:6})
    //                 .to(0.2,{angle:-6})
    //                 .to(0.2,{angle:0})
    //                 .delay(1)
    //             )
                .start();
        } else {
            this._sz_tip.stopAllActions();
            if(this._sz_tip.active){
                let entry = this._sz_tip.getComponent(sp.Skeleton).setAnimation(0,"animation3",false);
                this._sz_tip.getComponent(sp.Skeleton).setTrackCompleteListener(entry,()=>{
                    self._sz_tip.active = false;
                })
            }
        }
    },

    clickSzBtn(){
        if(!this._canClick){
            return
        }

        this.setCanClick(false);

        this.onSendSeq();
        // this.playSzAnim();
    },

    onSendSeq:function(){
        let req = {c: MsgId.SLOT_SUBGAME_DATA};
        req.gameid = cc.vv.gameData.getGameId()
        req.data = {
            rtype:this._rtype
        }
        cc.vv.NetManager.send(req,true);
    },

    onRcvSubGameAction(msg){
        cc.log(msg);
        if(msg.code === 200 && msg.data && msg.data.rtype == this._rtype){
            this._mapGame = msg.data.mapGame;
            this._diceInfo = msg.data.diceInfo;

            this.showClickResult();
        }
    },


    // 点击转动结果
    async showClickResult(){
        this._diceId = this._diceInfo.diceId;  // 色子序号
        this._step = this._diceInfo.step;      // 需要走的步数
        this._addCoin = this._diceInfo.addCoin; // 奖励的金币
        this._addFreeCnt = this._diceInfo.addFreeCnt;   //增加的免费次数
        this._addReel = this._diceInfo.addReel; // 增加slot
        this._addRow = this._diceInfo.addRow; // 增加行数
        this._addWildCol = this._diceInfo.addWildCol; // 增加列
        this._pawCnt = this._diceInfo.pawCnt; // 爪子数
        this._isEnd = this._diceInfo.isEnd; // 结束

        let curStep = this._mapGame.currStep;   // 当前位置

        this.playSzIdleAnim(false);
        await this.playSzAnim();
        await cc.vv.gameData.awaitTime(0.5);
        if(this._step && this._step > 0){   // 移动步数
            await this.playDogMove1();

            // if(this._curStep == this._jumpItem[0][0])
            // 跳转

            if(curStep != this._curStep) { // 跳转
                if(this._addReel > 0 || this._addWildCol > 0){
                }else {
                    this._addCoin = this._addCoin/2;
                    this._mapGame.winCoin -= this._addCoin

                }
            }

            if(this._addCoin && this._addCoin > 0){ // 赢金币
                await this.playWinCoin();
            } else if(this._addFreeCnt > 0){    // 增加免费次数
                await this.playWinFreeCnt();
            } else if(this._addReel > 0 || this._addRow > 0 || this._addWildCol > 0){  // 增加slot、增加行数
                await this.playWinSlots();
            }
        } else if(this._pawCnt && this._pawCnt > 0){ // 增加爪子
            Global.SlotsSoundMgr.playEffect("fly2");

            this._spine_fei.active = true;
            this._spine_fei.getComponent(sp.Skeleton).setAnimation(0,"animation",false);
            await cc.vv.gameData.awaitTime(0.5);

            this.updatePawNum(this._pawCnt);
        }

        if(curStep != this._curStep){ // 跳转
            await this.playDogMove2(curStep);
            if(this._addReel > 0 || this._addWildCol > 0){
                await this.playWinSlots();
            } else {
                this._mapGame.winCoin += this._addCoin;
                await this.playWinCoin();
            }
        }


        if(this._isEnd){    // 结束
            this.endMapGame();
        } else {
            this.setCanClick(true);
            this.playSzIdleAnim(true);
        }

    },

    // 色子转动
    playSzAnim(){
        return new Promise((success, failed)=>{
            Global.SlotsSoundMgr.playEffect("dice_spin");

            let self = this;
            // this._spr_sz.active = false;
            // this._spine_sz.active = true;
            let skin = this._diceId > 6 ? (this._diceId-6)*100 : this._diceId;
            this._spine_sz.getComponent(sp.Skeleton).setSkin("sz"+skin);
            this._spine_sz.getComponent(sp.Skeleton).setAnimation(0,"animation", false);
            this._spine_sz.getComponent(sp.Skeleton).setCompleteListener(()=>{
                Global.SlotsSoundMgr.playEffect("dice_stop");
                // self._spine_sz.active = false;
                // self._spr_sz.active = true;
                // self._diceId = self._diceInfo.diceId;  // 色子序号
                // self.setSzSpr(self._diceId);
                success()
            })
        })
    },

    // 狗跳动
    playDogMove1(){
        return new Promise(async(success, failed)=>{
            for (let i = 0; i < this._step; i++){
                Global.SlotsSoundMgr.playEffect("dog1");

                this._curStep += 1;
                cc.log("this._curStep",this._curStep)
                this._spine_dog.getComponent(sp.Skeleton).setAnimation(0,"animation2",false);
                let endPos = cc.v2(this._itemList[this._curStep-1].x, this._itemList[this._curStep-1].y-20)
                cc.tween(this._spine_dog).to(0.5, {position:endPos}).start()

                await cc.vv.gameData.awaitTime(0.7)
                if(this._curStep >= this._itemList.length) break;
            }
            this._spine_dog.getComponent(sp.Skeleton).setAnimation(0,"animation1",true);

            success();
        })
    },

    // 狗跳转
    playDogMove2(curStep){
        return new Promise(async(success, failed)=>{
            Global.SlotsSoundMgr.playEffect("dog2");
            // this._curStep += curStep;
            this._curStep = curStep;
            this._spine_dog.getComponent(sp.Skeleton).setAnimation(0,"animation2",false);

            let startPos = this._spine_dog.position;
            let endPos = cc.v2(this._itemList[curStep-1].position.x, this._itemList[curStep-1].position.y-20);
            if(curStep == 6){   //
                let cetPos = cc.v2(startPos.x-100, startPos.y-100);
                cc.tween(this._spine_dog).bezierTo(0.8,startPos,cetPos, endPos).start();
                await cc.vv.gameData.awaitTime(0.8);
                this._node_road1.active = true;
                this._node_road1.getComponent(sp.Skeleton).setAnimation(0,"animation2", false);
                this._spr_road1.active = false;
            } else {
                cc.tween(this._spine_dog).to(0.8, {position:endPos}).start();
                await cc.vv.gameData.awaitTime(0.8);
                this._node_road2.active = true;
                this._node_road2.getComponent(sp.Skeleton).setAnimation(0,"animation1", false);
                this._spr_road2.active = false;
            }

            // await cc.vv.gameData.awaitTime(0.8)
            this._spine_dog.getComponent(sp.Skeleton).setAnimation(0,"animation1",true);

            success();
        })
    },

    // 播放赢钱奖励
    playWinCoin(){
        return new Promise(async(success, failed)=> {
            Global.SlotsSoundMgr.playEffect("coin");

            this._par_win.active = true;
            this._par_win.getComponent(cc.ParticleSystem).resetSystem();
            this._par_win.position = this._par_win.parent.convertToNodeSpaceAR(this._itemList[this._curStep - 1].convertToWorldSpaceAR(cc.v2(0, 0)));
            let lbl = cc.find("lbl", this._par_win);
            lbl.active = true;

            lbl.setScale(1);
            lbl.getComponent(cc.Label).string = Global.formatNumShort(this._addCoin, 1);
            await cc.vv.gameData.awaitTime(1);

            let endNode = cc.find("safe_node/LMSlots_Bottom/winBg/lbl_winNum_nor", this.node);
            let endPos = this._par_win.parent.convertToNodeSpaceAR(endNode.convertToWorldSpaceAR(cc.v2(0, 0)));
            cc.tween(lbl).to(0.5, {scale: 0.2}).start();
            cc.tween(this._par_win).to(0.5, {position: endPos}).start();

            await cc.vv.gameData.awaitTime(0.5);
            this._par_win.active = false;
            cc.vv.gameData.GetBottomScript().SetWin(this._mapGame.winCoin);

            success();
        });
    },

    // 播放赢免费次数
    playWinFreeCnt(){
        return new Promise(async(success, failed)=> {
            Global.SlotsSoundMgr.playEffect("fly4");

            this._par_win.active = true;
            this._par_win.getComponent(cc.ParticleSystem).resetSystem();
            cc.find("lbl", this._par_win).active = false;
            let item = this._itemList[this._curStep - 1]
            let spr = cc.find("spr", item);
            spr.active = false
            let cpr_copy = cc.instantiate(spr);
            cpr_copy.parent = this._par_win;
            cpr_copy.active = true;

            this._par_win.position = this._par_win.parent.convertToNodeSpaceAR(item.convertToWorldSpaceAR(cc.v2(0, 0)));
            let endPos = this._par_win.parent.convertToNodeSpaceAR(this._lbl_free_cnt.convertToWorldSpaceAR(cc.v2(0, 0)));
            cc.tween(this._par_win).to(0.5, {position: endPos}).start();
            cc.tween(item).to(0.5, {opacity:0}).start();

            await cc.vv.gameData.awaitTime(0.5);
            cpr_copy.destroy();
            this._par_win.active = false;
            this._par_freeCnt.active = true;
            this._par_freeCnt.getComponent(cc.ParticleSystem).resetSystem();
            this.setFreeCnt();

            success();
        })
    },

    // 卷轴发生改变
    playWinSlots(){
        return new Promise(async(success, failed)=> {
            Global.SlotsSoundMgr.playEffect("fly3");

            this._par_win.active = true;
            this._par_win.getComponent(cc.ParticleSystem).resetSystem();
            cc.find("lbl", this._par_win).active = false;
            let item = this._itemList[this._curStep - 1]
            let spr = cc.find("spr", item);
            spr.active = false
            let cpr_copy = cc.instantiate(spr);
            cpr_copy.parent = this._par_win;
            cpr_copy.active = true;

            this._par_win.position = this._par_win.parent.convertToNodeSpaceAR(item.convertToWorldSpaceAR(cc.v2(0, 0)));
            let endPos = this._par_win.parent.convertToNodeSpaceAR(this._node_freeType.convertToWorldSpaceAR(cc.v2(0, 0)));
            cc.tween(this._par_win).to(0.5, {position: endPos}).start();
            cc.tween(item).to(0.5, {opacity:0}).start();

            await cc.vv.gameData.awaitTime(0.5);
            cpr_copy.destroy();
            this._par_win.active = false;
            this._par_freeType.active = true;
            this._par_freeType.getComponent(cc.ParticleSystem).resetSystem();

            this.initFreeType();

            success();
        })
    },

    // update (dt) {},
});
