
cc.Class({
    extends: require("LMSlots_GameData_Base"),

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start() {

    },

    //deskInfo进入游戏获得的服务端数据
    init(deskInfo, gameId, gameJackpot) {
        this._epicInfo = deskInfo.epicInfo;
        if (deskInfo.epicInfo) {
            this._bonusIdxs = deskInfo.epicInfo.bonusIdxs;
            this._bonusItems = deskInfo.epicInfo.bonusItems;
        }

        this._mapGame = deskInfo.mapGame
        if (deskInfo.mapGame) {
            this._freeSlotsCnt = deskInfo.mapGame.slotCnt;
            this._freeAddRow = deskInfo.mapGame.extraRow;
            this._freeWildCols = deskInfo.mapGame.wildCols;
        }

        if (deskInfo.pageReward) {
            this._freeSlotsCnt = deskInfo.pageReward.slotCnt;
            this._freeAddRow = 1;
            this._freeWildCols = deskInfo.pageReward.wildCols;
        }

        this._pawStore = deskInfo.pawStore;


        this._freeWinCoin = deskInfo.freeWinCoin

        this._super(deskInfo, gameId, gameJackpot);
    },

    //重写接收旋转消息
    OnRcvNetSpine(msg) {
        if (msg.code == 200) {
            this._epicInfo = msg.epicInfo;
            this._bonusIdxs = msg.bonusIdxs;
            this._bonusItems = msg.bonusItems;

            this._mapGame = msg.mapGame;


            this._pawStore = msg.pawStore;

            this._freeWinCoin = msg.freeWinCoin
        }

        this._super(msg);
    },


    setPopupScript(scp) {
        this._popScp = scp;
    },
    getPopupScript() {
        return this._popScp;
    },

    setBonusScript(scp) {
        this._bonusScp = scp;
    },
    getBonusScript() {
        return this._bonusScp;
    },

    setMapScript(scp) {
        this._mapScp = scp
    },
    getMapScript() {
        return this._mapScp;
    },

    setFreeScript(scp) {
        this._freeScp = scp
    },
    getFreeScript() {
        return this._freeScp;
    },

    setStoreScript(scp) {
        this._storeScp = scp
    },
    getStoreScript() {
        return this._storeScp;
    },

    getNeedBet() {
        return this._deskInfo.needBet
    },

    setIsBonusGame(val) {
        this._isBonusGame = val;
    },
    isBonusGame() {
        return this._isBonusGame;
    },

    setEpicInfo(val) {
        this._epicInfo = val;
    },
    getEpicInfo() {
        return this._epicInfo;
    },

    setBonusIdxs(val) {
        this._bonusIdxs = val;
    },
    getBonusIdxs() {
        return this._bonusIdxs;
    },

    setBonusItems(val) {
        this._bonusItems = val;
    },
    getBonusItems() {
        return this._bonusItems;
    },

    setMapGame(val) {
        this._mapGame = val;
    },
    getMapGame() {
        return this._mapGame;
    },


    setIsFreeGame(val) {
        this._isFreeGame = val;
    },
    isFreeGame() {
        return this._isFreeGame;
    },

    // 免费游戏增加的行数(默认3行)
    setFreeAddRow(row) {
        this._freeAddRow = row;
    },
    getFreeAddRow() {
        return this._freeAddRow;
    },

    // 免费游戏卷轴个数
    setFreeSlotsCnt(val) {
        this._freeSlotsCnt = val;
    },
    getFreeSlotsCnt() {
        return this._freeSlotsCnt;
    },

    // 免费wild所在的列
    setFreeWildCols(val) {
        this._freeWildCols = val;
    },
    getFreeWildCols() {
        return this._freeWildCols;
    },

    getFreeGameSlots() {
        return this._gameInfo.freeGameSlots;
    },

    getFreeWinCoin() {
        return this._freeWinCoin;
    },

    setPawStore(val) {
        this._pawStore = val;
    },
    getPawStore() {
        return this._pawStore;
    },



    _doPauseAction: function (bPause) {
        this._super(bPause)

        let pauseActionNode = []
        let FreeSlotCmp = this.getFreeScript()
        if (FreeSlotCmp) {
            FreeSlotCmp.enabled = bPause

            for (let slot_i = 0; slot_i < FreeSlotCmp._slotsScpList.length; slot_i++) {
                let slotCmp = FreeSlotCmp._slotsScpList[slot_i];

                let reels = slotCmp._reels
                for (let i = 0; i < reels.length; i++) {
                    let item = reels[i]
                    item.enabled = bPause
                    let symbols = item._symbols
                    for (let j = 0; j < symbols.length; j++) {
                        let sysItem = symbols[j]
                        sysItem.enabled = bPause
                        pauseActionNode.push(sysItem.node)
                    }
                }
            }


        }

        for (let it = 0; it < pauseActionNode.length; it++) {
            if (pauseActionNode[it].active) {
                if (!bPause) {
                    pauseActionNode[it].pauseAllActions()       //暂停此节点action
                }
                else {
                    pauseActionNode[it].resumeAllActions()       //恢复此节点action
                }

            }

            let symChild = pauseActionNode[it].children //暂停子节点action
            for (let k = 0; k < symChild.length; k++) {
                if (symChild[k].active) {

                    if (!bPause) {
                        symChild[k].pauseAllActions()
                    }
                    else {
                        symChild[k].resumeAllActions()
                    }
                }

            }
        }
    }



    // update (dt) {},
});
