
cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start() {

    },

    Init() {
        this._btn_entrance = cc.find("btn_entrance", this.node);
        this._spr_bonusType = cc.find("spr_bonusCnt", this.node);
        Global.btnClickEvent(this._spr_bonusType, this.onclickBonusType, this);

        this._normalSpine = cc.find("reels/spine", this.node);
        this._normalSpine.on("click", this.slotsSpine, this);
        this._normalSpine.getComponent(cc.Button).interactable = false;
        this._stopNode = cc.find("reels/stop", this.node);
        this._stopNode.active = false;
        this._stopNode.on("click", this.onStop, this);

        this._super();

        this.showBonusType();
    },

    RegisterEvent: function () {
        this._super();

        Global.registerEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED, this.onEventTotalbetUpdated, this)// 押注额改变
    },

    //断线重连的显示
    async ReconnectShow() {
        this._topScript.SetBackLobby(false);
        this._bottomScript.ShowBtnsByState("moveing_1")

        let epicInfo = cc.vv.gameData.getEpicInfo();
        if (epicInfo) {
            this.showBonusGameView(true);
            this.Backup();
            this.setAllSymbolMask(true);
            this.initBonusSymbol();
            this._bottomScript.SetWin(0);

            // await cc.vv.gameData.awaitTime(2);
            await cc.vv.gameData.getBonusScript().enterBonusGame();

            cc.vv.gameData.getPopupScript().playQPAnim2();
            await cc.vv.gameData.awaitTime(0.7);
            this.showBonusGameView(false);
            this.Resume();
            this.setAllSymbolMask(false);
            await cc.vv.gameData.awaitTime(1);
        }
        else {
            this.showBonusGameView(false);
        }

        let allFreeCnt = cc.vv.gameData.GetTotalFree();
        if (allFreeCnt > 0) {
            await cc.vv.gameData.getFreeScript().initShowSlotsData(false);
        }

        let mapGame = cc.vv.gameData.getMapGame()
        if (mapGame && mapGame.state == 1) {
            await cc.vv.gameData.getMapScript().showMapGame();
        }

        this._topScript.StopMove()
        this._bottomScript.CanDoNextRound();
    },


    // 断线时，显示bonus图标
    initBonusSymbol() {
        let bonusIdxs = cc.vv.gameData.getBonusIdxs();
        let bonusItems = cc.vv.gameData.getBonusItems();

        bonusIdxs.forEach(idx => {
            this._reels[idx - 1].GetSymbolByRow(0).ShowById(3, bonusItems[bonusIdxs.indexOf(idx)])
            this._reels[idx - 1].GetSymbolByRow(0).playBonusIdleAnim();
        })
    },

    slotsSpine() {
        this._bottomScript.OnClickSpin()
    },

    onStop() {
        this._stopNode.active = false;
        this._bottomScript.OnClickStop()
    },

    setStopNodeState(bShow) {
        this._stopNode.active = bShow;
    },

    //可以进入下一局
    //如果是自动模式/免费模式，调用此接口会开始自动旋转，
    //普通模式的话，调用此接口。按钮都会变成可点击状态
    CanDoNextRound: function () {
        this._super()
        this._normalSpine.getComponent(cc.Button).interactable = this._bottomScript.GetSpinBtnState()
    },

    StartMove() {
        this._normalSpine.getComponent(cc.Button).interactable = false;

        if (cc.vv.gameData.isBonusGame()) {
            this.bonusStartMove();
        }
        else if (cc.vv.gameData.isFreeGame()) {
            cc.vv.gameData.getFreeScript().StartMove();
        }
        else {
            this._super();
            Global.SlotsSoundMgr.playNormalBgm();
            this._isSpinEnd = false;
        }

    },

    StopMove() {
        if (cc.vv.gameData.isFreeGame()) {
            cc.vv.gameData.getFreeScript().StopMove();
        }
        else {
            this._super();
        }
    },

    // bonus游戏开始旋转
    bonusStartMove() {
        this._bStopRightnow = null
        // this._gameInfo = null

        //top状态更新
        this._topScript.StartMove()

        //清理数据
        cc.vv.gameData.ClearOneRoundData()

        this._reelMax = [];

        // 部分列转起来
        let reels = [];
        let reelIdxs = []
        let bonusIdxs = cc.vv.gameData.getBonusIdxs();
        this._reels.forEach(reel => {
            if (!bonusIdxs.includes(reel.GetReelIdx() + 1)) {
                reels.push(reel)
                reelIdxs.push(reel.GetReelIdx())
            }
        })
        this.MoveReels(reels)
        this.setMoveLastIdx(reelIdxs)


        //设置停止时间
        //就是从开始旋转，如果多少秒会开始停止
        this._stopTime = this.GetStopTime()
    },

    setMoveLastIdx(reelIdxs) {
        let max = reelIdxs[0];
        let reelMax = [];
        reelIdxs.forEach(idx => {
            if (idx % 5 > max % 5 || (idx % 5 == max % 5 && idx / 3 > max / 3)) {
                max = idx;
            }

            reelMax[idx % 5] = reelMax[idx % 5] ? Math.max(reelMax[idx % 5], idx) : idx;
        });
        this.moveReelLastIdx = max;
        cc.log("StartMove：this.moveReelLastIdx:", this.moveReelLastIdx);
        this._reelMax = reelMax;
        cc.log(this._reelMax)
    },

    // 获取一竖排中最后的那个列
    getLastStopReel() {
        return this._reelMax
    },

    SetSlotsResult: function (cards) {
        //把结果按卷轴结果整理
        let acRow = cards.length / this._col
        let reelResults = []
        let bonusIdxs = cc.vv.gameData.getBonusIdxs();
        if (!Array.isArray(bonusIdxs)) { bonusIdxs = [] } // By JerryWong
        let bonusItems = cc.vv.gameData.getBonusItems();
        for (let i = 0; i < cards.length; i++) {
            let row = Math.floor(i / acRow)
            let col = i % this._col
            //配置中有没有这个元素
            if (this._cfg.symbol[cards[i]]) {
                let res = {}
                res.sid = cards[i] //符号id
                res.data = {};
                if (bonusIdxs && bonusIdxs.includes(i + 1)) {
                    res.data = bonusItems[bonusIdxs.indexOf(i + 1)];
                }
                if (!reelResults[col]) reelResults[col] = []
                reelResults[col].unshift(res)
            }
        }
        for (let i = 0; i < this._reels.length; i++) {
            let item = this._reels[i]
            let reelRes = reelResults[i]
            item.SetResult(reelRes)
        }
    },

    SetReelStateInfo: function (cards) {
        if (!this._cfg.reelStateInfo) {
            return;
        }
        let reelResults = []
        for (let i = 0; i < cards.length; i++) {
            let id = cards[i]
            let col = i % 5
            if (!reelResults[col]) reelResults[col] = []
            reelResults[col].push(id)
        }
        for (let info of this._cfg.reelStateInfo) {
            let stateInfo = Global.copy(info);
            stateInfo.isStop = false
            stateInfo.isAnt = false
            let triggerCount = stateInfo.mini
            let countsConfig = Global.copy(stateInfo.counts);
            let haveCount = 0
            let isContinuous = true
            for (let i = 0; i < reelResults.length; i++) {
                let item = this._reels[i]
                let reelRes = reelResults[i]
                stateInfo.isStop = false
                stateInfo.isAnt = false
                if (haveCount >= triggerCount - 1 && stateInfo.counts[i] > 0 && isContinuous) {  //满足条件 需要播放加速框
                    stateInfo.isAnt = true
                }
                let reelCountOfID = reelRes.reduce((a, v) => stateInfo.id.includes(v) ? a + 1 : a + 0, 0);
                haveCount += reelCountOfID
                countsConfig.shift()
                let remainingCount = (countsConfig.length > 0 ? countsConfig.reduce((x, y) => x + y) : 0) + haveCount
                if (reelCountOfID > 0 && remainingCount >= triggerCount && isContinuous) {  //满足条件 播放停止动画和停止音效
                    stateInfo.isStop = true
                }
                if (stateInfo.continuous && stateInfo.counts[i] > 0 && reelCountOfID == 0) {
                    isContinuous = false
                }
                item.AddReelStateInfo(Global.copy(stateInfo))
                for (let j = 1; j < 4; j++) {
                    let item_1 = this._reels[j * 5 + i];
                    let info_1 = Global.copy(stateInfo);
                    info_1.isAnt = false;
                    info_1.noEff = true;
                    item_1.AddReelStateInfo(info_1);
                }
            }
        }
    },

    //配置了加速节点才显示，如果点击了立即停止(_bStopRightnow)也不显示了。
    //每列停止后，会自动隐藏加速节点
    DoCheckReelAnti: function (colIdx) {
        if (!this._bStopRightnow) {
            let isPlayAnit = false
            for (let i = 0; i < this._reels.length; i++) {
                let idx = this._reels[i].GetReelIdx()
                if (idx == colIdx + 1) {
                    isPlayAnit = this._reels[i].playAntiAnimation()
                }
                if (idx % 5 > colIdx % 5 && isPlayAnit) {//加速显示的时候，多转1s
                    let nAddSpeedTime = cc.vv.gameData.getGameCfg().AddAntiTime || 1
                    this._reels[i].AddDelayTime(nAddSpeedTime)
                }
            }
        }
    },

    onMsgSpine(msg) {
        if (cc.vv.gameData.isFreeGame()) {
            cc.vv.gameData.getFreeScript().onMsgSpine(msg);
        }
        else {
            // msg.resultCards = [2,2,7,7,7, 8,8,8,8,8, 9,9,9,9,9, 6,6,6,6,6]
            this._super(msg);
        }
    },

    OnReelSpinEnd(colIdx) {
        if (cc.vv.gameData.isBonusGame()) {
            if (this._reels[colIdx].GetSymbolByRow(0).GetShowId() == 3) {
                this._reels[colIdx].GetSymbolByRow(0).playBonusIdleAnim();
                Global.SlotsSoundMgr.playEffect("symbol_coin");
            }
            if (colIdx == this._reelMax[colIdx % 5]) {
                Global.SlotsSoundMgr.playEffect("reel_stop");
            }
        } else {
            // 爪子
            let pawInfo = this._gameInfo.pawInfo;
            if (pawInfo && pawInfo.totalCnt > 0) {
                let cnts = pawInfo.cnts;
                let idxs = pawInfo.idxs;
                for (let i = 0; i < idxs.length; i++) {
                    if (idxs[i] == colIdx + 1) {
                        if (!this._isSpinEnd) {
                            this.GetSymbolByIdx(idxs[i]).showPaw(this.getPawAnimType(cnts[i]));
                        }
                        break;
                    }
                }
            }
            this._super(colIdx);
        }
    },

    OnSpinEnd() {
        if (cc.vv.gameData.isBonusGame()) {
            cc.vv.gameData.getBonusScript().onBonusSpinEnd();
        }
        else if (cc.vv.gameData.isFreeGame()) {
            cc.vv.gameData.getFreeScript().OnSpinEnd();
        }
        else {
            this.onSpinEndAction();
        }
    },

    async onSpinEndAction() {
        this._isSpinEnd = true;
        let pawInfo = this._gameInfo.pawInfo;
        if (pawInfo && pawInfo.totalCnt > 0) {
            this.flyPaw();
        }
        // 显示中奖路线
        this.ShowWinTrace()
        // 显示底部赢钱
        let nWin = cc.vv.gameData.GetGameWin()
        let nTotal = nWin
        if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() != cc.vv.gameData.GetFreeTime()) {
            nTotal = cc.vv.gameData.getFreeWinCoin()
        }
        await new Promise((success, failed) => {
            this.ShowBottomWin(nWin, nTotal, true, success)
        });
        // 触发bonus
        if (this._gameInfo.epicInfo) {
            await this.triBonusGame();
        }
        // 触发地图
        if (this._gameInfo.mapGame) {
            await this.triMapGame();
        }
        this.CanDoNextRound();
    },

    // 初始化所有节点，
    initAllSymbol() {
        for (let col = 0; col < this._reels.length; col++) {
            for (let row = 0; row < this._row; row++) {
                this._reels[col].GetSymbolByRow(row).ClearState();
            }
        }
    },

    // 触发bonus游戏
    triBonusGame() {
        return new Promise(async (success, failed) => {
            Global.SlotsSoundMgr.playEffect("trigger_respin");
            await cc.vv.gameData.awaitTime(0.5);
            await cc.vv.gameData.getPopupScript().playTriBonusAnim();
            cc.vv.gameData.getPopupScript().playQPAnim2();
            await cc.vv.gameData.awaitTime(0.7);
            this.showBonusGameView(true);
            this.Backup();
            this.initAllSymbol();   // 清除节点播放动画状态
            this.setAllSymbolMask(true);
            this._bottomScript.SetWin(0);
            for (let i = 0; i < this._gameInfo.bonusIdxs.length; i++) {
                this.GetSymbolByIdx(this._gameInfo.bonusIdxs[i]).playBonusIdleAnim();
            }
            // await cc.vv.gameData.awaitTime(2);
            await cc.vv.gameData.getBonusScript().enterBonusGame();
            cc.vv.gameData.getPopupScript().playQPAnim2();
            await cc.vv.gameData.awaitTime(0.7);
            this.showBonusGameView(false);
            this.Resume();
            this.setAllSymbolMask(false);
            await cc.vv.gameData.awaitTime(1);
            success();
        });
    },

    // 触发地图游戏
    triMapGame() {
        return new Promise(async (success, failed) => {
            let idxs = this._gameInfo.scatterIdxs;
            for (let i = 0; i < idxs.length; i++) {
                let symbol = this.GetSymbolByIdx(idxs[i]);
                if (symbol) {
                    symbol.playTriggerAnimation();
                }
            }
            Global.SlotsSoundMgr.playEffect("bell");
            Global.SlotsSoundMgr.playEffect("trigger_fg");
            await cc.vv.gameData.awaitTime(2);
            await cc.vv.gameData.getPopupScript().playTriMapAnim();
            cc.vv.gameData.getPopupScript().playQPAnim3();
            await cc.vv.gameData.awaitTime(0.7);
            await cc.vv.gameData.getMapScript().showMapGame();
            success();
        })
    },


    //每列停止时间间隔 = 每列的停止间隔 + 每列的回弹时间
    //reelIdx:0开始
    GetReelStopInter: function (reelIdx) {
        let nIter = this._cfg.reelStopInter || 0.6
        return reelIdx % 5 * nIter
    },

    // bonus触发类型
    showBonusType() {
        let curBet = cc.vv.gameData.GetBetIdx();
        let needBet = cc.vv.gameData.getNeedBet();

        let spr_5 = cc.find("spr_5", this._spr_bonusType);
        let spr_6 = cc.find("spr_6", this._spr_bonusType);
        if (curBet >= needBet) {
            spr_5.active = true;
            spr_6.active = false;
        } else {
            spr_5.active = false;
            spr_6.active = true;
        }
    },

    // 点击bonus类型图片
    onclickBonusType() {
        if (!cc.vv.gameData.GetBottomScript().GetSpinBtnState()) return;
        if (cc.vv.gameData.GetAutoModelTime() > 0) return;
        if (cc.vv.gameData.isFreeGame()) return;
        if (cc.vv.gameData.isBonusGame()) return;

        let spr_6 = cc.find("spr_6", this._spr_bonusType);
        if (spr_6.active) {
            let needBet = cc.vv.gameData.getNeedBet();
            let allMults = cc.vv.gameData.GetBetMults();

            if (needBet > allMults.length) {
            } else {
                cc.vv.gameData.GetBottomScript().SetBetIdx(needBet)
            }
        }
    },

    // 押注额改变
    onEventTotalbetUpdated() {
        let curBet = cc.vv.gameData.GetBetIdx();
        let needBet = cc.vv.gameData.getNeedBet();

        let spr_5 = cc.find("spr_5", this._spr_bonusType);
        let spr_6 = cc.find("spr_6", this._spr_bonusType);
        if (curBet >= needBet && spr_6.active) {
            Global.SlotsSoundMgr.playEffect("change_dialog");
            spr_5.active = true;
            spr_6.active = false;
            cc.tween(spr_5).to(0.3, { scale: 1.1 }).to(0.2, { scale: 1 }).start();
        } else if (curBet < needBet && spr_5.active) {
            Global.SlotsSoundMgr.playEffect("change_dialog");
            spr_5.active = false;
            spr_6.active = true;
            cc.tween(spr_6).to(0.3, { scale: 1.1 }).to(0.2, { scale: 1 }).start();
        }
    },

    async flyPaw() {
        let pawInfo = this._gameInfo.pawInfo;
        let cnts = pawInfo.cnts;
        let idxs = pawInfo.idxs;

        let paw_fly = cc.find("btn_entrance/node_fly", this.node);
        for (let i = 0; i < idxs.length; i++) {

            let flyNode = cc.instantiate(paw_fly);
            flyNode.active = true;
            flyNode.parent = paw_fly.parent;

            let paw = this.GetSymbolByIdx(idxs[i]).getPaw();
            let startPos = flyNode.convertToNodeSpaceAR(paw.convertToWorldSpaceAR(cc.v2(0, 0)));
            let fly_paw = cc.instantiate(paw);
            fly_paw.active = true;
            fly_paw.parent = flyNode;
            fly_paw.position = startPos;
            let animName = cc.js.formatStr("animation%s", this.getPawAnimType(cnts[i]));
            fly_paw.getComponent(sp.Skeleton).setAnimation(0, animName, false);
            cc.tween(fly_paw).to(0.5, { position: cc.v2(-38, 35) }).start();

            let fly_par = cc.find("par_tw", flyNode);
            fly_par.position = cc.v2(startPos.x + 38, startPos.y - 35);
            cc.tween(fly_par).to(0.5, { position: cc.v2(0, 0) }).start();

            cc.tween(flyNode).delay(0.5).call(() => { flyNode.destroy() }).start();
            this.GetSymbolByIdx(idxs[i]).showPaw();
        }

        Global.SlotsSoundMgr.playEffect("fly1");
        await cc.vv.gameData.awaitTime(0.5);
        cc.vv.gameData.getStoreScript().playWinPawAnim();
    },

    getPawAnimType(cnt) {
        let name = "";
        if (cnt === 5) {
            name += 1;
        } else if (cnt === 10) {
            name += 2;
        } else if (cnt === 15) {
            name += 3;
        } else if (cnt === 20) {
            name += 4;
        } else if (cnt === 25) {
            name += 5;
        } else if (cnt === 30) {
            name += 6;
        } else if (cnt === 35) {
            name += 7;
        } else if (cnt === 40) {
            name += 8;
        } else if (cnt === 50) {
            name += 9;
        }

        return name;
    },

    setBonusCanStop(val) {
        this._bonusCanStop = val
    },

    //如果收到结果不需要里面进入停止节奏，可通过重写此接口来实现自己控制
    //默认是收到结果就停止
    CanStopSlot() {
        let canStop = this._gameInfo != null;
        if (cc.vv.gameData.isBonusGame()) {
            canStop = this._bonusCanStop;
        }
        return canStop
    },

    // 显示bonus game 页面
    showBonusGameView(isBonus) {
        cc.vv.gameData.setIsBonusGame(isBonus);
        cc.vv.gameData.getStoreScript().showEntranceBtn(!isBonus);
        this._spr_bonusType.active = !isBonus;

        if (isBonus) {
            // 奖池锁定
            let epicInfo = cc.vv.gameData.getEpicInfo();
            this.lockJackpot(epicInfo.jackpotValues);

        } else {
            this.unlockJackpot();
            cc.vv.gameData.getBonusScript().showBonusSpins(false)
        }

        cc.find("Canvas/safe_node/spr_bg_normal").active = !isBonus;
        cc.find("Canvas/safe_node/spr_bg_bonus").active = isBonus;
        cc.find("Canvas/safe_node/spine_character").opacity = 255;
    },

    //奖池锁定(停止滚动)
    lockJackpot(jackpotvalus) {
        let prizepool = cc.find("Canvas/safe_node/LMSlots_PrizePool_1").getComponent("LMSlots_PrizePool_Base");
        prizepool.PausePool([{ prizeType: 0, pauseNum: jackpotvalus[0] }, { prizeType: 1, pauseNum: jackpotvalus[1] },
        { prizeType: 2, pauseNum: jackpotvalus[2] }, { prizeType: 3, pauseNum: jackpotvalus[3] }]);
    },

    //恢复奖池
    unlockJackpot() {
        let prizepool = cc.find("Canvas/safe_node/LMSlots_PrizePool_1").getComponent("LMSlots_PrizePool_Base");
        prizepool.ResumePausePool();
    },

    // 设置所有节点是否置灰
    setAllSymbolMask(isMask) {
        this._reels.forEach(reel => {
            reel.GetSymbolByRow(0).setMaskVisible(isMask);
            reel.GetSymbolByRow(1).setMaskVisible(isMask);
        });
    },


    // update (dt) {},
});
