cc.Class({
    extends: cc.Component,

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    Init(){
        this._node_popup = cc.find("safe_node/node_popup", this.node);
        this._node_popup.active = false;

        this._node_tri_bonus = cc.find("node_tri_bonus", this._node_popup);
        this._node_tri_map = cc.find("node_tri_map", this._node_popup);
        this._node_tri_free = cc.find("node_tri_free", this._node_popup);
        this._node_end_free = cc.find("node_end_free", this._node_popup);
        this._node_tri_superFree = cc.find("node_tri_superFree", this._node_popup);
        this._node_unlock_page = cc.find("node_unlock_page", this._node_popup);
        this._node_tri_bonus_again = cc.find("node_tri_bonus_again", this._node_popup);
        this._node_tri_bonus.active = false;
        this._node_tri_map.active = false;
        this._node_tri_free.active = false;
        this._node_end_free.active = false;
        this._node_tri_superFree.active = false;
        this._node_unlock_page.active = false;
        this._node_tri_bonus_again.active = false;


        this._node_qp = cc.find("safe_node/node_qp", this.node);
        this._node_qp.active = false;

        this._qieping_1 = cc.find("qieping_01", this._node_qp); //骰子
        this._qieping_2 = cc.find("qieping_02", this._node_qp); //金币
        this._qieping_3 = cc.find("qieping_03", this._node_qp); //人物
        this._qieping_1.active = false;
        this._qieping_2.active = false;
        this._qieping_3.active = false;
    },

    // 触发bonus
    playTriBonusAnim(){
        return new Promise(async (success, failed)=> {
            Global.SlotsSoundMgr.playEffect("normal_dialog_show4");

            this._node_popup.active = true;
            this._node_tri_bonus.active = true;
            this._node_tri_bonus.setScale(0);
            cc.tween(this._node_tri_bonus).to(0.5, {scale:1}, {easing:"backOut"}).start();

            await cc.vv.gameData.awaitTime(2);
            cc.tween(this._node_tri_bonus).to(0.5, {scale:0}, {easing:"backIn"}).start()

            await cc.vv.gameData.awaitTime(0.5);
            this._node_tri_bonus.active = false;
            this._node_popup.active = false;

            success();
        });
    },

    // 触发地图
    playTriMapAnim(){
        return new Promise(async (success, failed)=> {
            Global.SlotsSoundMgr.playEffect("map_dialog");

            this._node_popup.active = true;
            this._node_tri_map.active = true;
            this._node_tri_map.setScale(0);
            cc.tween(this._node_tri_map).to(0.5, {scale:1}, {easing:"backOut"}).start();

            await cc.vv.gameData.awaitTime(2);
            cc.tween(this._node_tri_map).to(0.5, {scale:0}, {easing:"backIn"}).start()

            await cc.vv.gameData.awaitTime(0.5);
            this._node_tri_map.active = false;
            this._node_popup.active = false;

            success();
        });
    },

    // 触发免费
    playTriFreeAnim(){
        return new Promise(async(success, failed)=>{
            Global.SlotsSoundMgr.playEffect("fg_dialog");

            this._node_popup.active = true;
            this._node_tri_free.active = true;
            this._node_tri_free.setScale(0);
            cc.tween(this._node_tri_free).to(0.5, {scale:1}, {easing:"backOut"}).start();

            let freeCnt = cc.vv.gameData.GetTotalFree();
            let addRow = cc.vv.gameData.getFreeAddRow();
            let slotsCnt = cc.vv.gameData.getFreeSlotsCnt();
            let wildCols = cc.vv.gameData.getFreeWildCols();

            let map_altas = cc.vv.gameData.GetAtlasByName("map");
            let dialog_altas = cc.vv.gameData.GetAtlasByName("dialog");
            cc.find("lbl_cnt", this._node_tri_free).getComponent(cc.Label).string = freeCnt;
            cc.find("spr_map", this._node_tri_free).getComponent(cc.Sprite).spriteFrame = map_altas.getSpriteFrame(addRow?"theme128_map_3":"theme128_map_6");
            for (let j = 1; j <= 5; j++){
                cc.find("spr_map/wild_"+j, this._node_tri_free).active = wildCols.includes(j);
                cc.find("spr_map/wild_"+j, this._node_tri_free).getComponent(cc.Sprite).spriteFrame = map_altas.getSpriteFrame(addRow?"theme128_map_2":"theme128_map_4")
            }
            cc.find("spr_cnt", this._node_tri_free).getComponent(cc.Sprite).spriteFrame = dialog_altas.getSpriteFrame("theme128_popup_free_cnt"+slotsCnt);

            await cc.vv.gameData.awaitTime(0.5);
            let btn_start = cc.find("bg_btn/btn_start", this._node_tri_free);
            btn_start.off("click");
            btn_start.getComponent(cc.Button).interactable = true;
            let self = this;

            let clickFunc = async()=>{
                Global.SlotsSoundMgr.playEffect("click1");
                Global.SlotsSoundMgr.playEffect("normal_dialog_close");
                btn_start.getComponent(cc.Button).interactable = false;
                cc.tween(self._node_tri_free).to(0.5, {scale:0}, {easing:"backIn"}).start();

                await cc.vv.gameData.awaitTime(0.5);
                self._node_popup.active = false;
                self._node_tri_free.active = false;
                success();
            };
            cc.vv.gameData.checkAutoPlay(btn_start, clickFunc);
            btn_start.on("click", async()=>{
                btn_start.stopAllActions();
                clickFunc();
            })
        })
    },

    // 结束免费
    playEndFreeAnim(){
        return new Promise(async(success, failed)=>{
            Global.SlotsSoundMgr.playEffect("normal_dialog_show2");

            this._node_popup.active = true;
            this._node_end_free.active = true;
            this._node_end_free.setScale(0);
            cc.tween(this._node_end_free).to(0.5, {scale:1}, {easing:"backOut"}).start();

            let wincoin = cc.vv.gameData.getFreeWinCoin();
            let lbl = cc.find("spr_tiao/lbl_cnt", this._node_end_free);
            Global.doRoallNumEff(lbl,0,wincoin, 1.5,null,null,0,true);

            await cc.vv.gameData.awaitTime(0.5);
            let btn_collect = cc.find("bg_btn/btn_collect", this._node_end_free);
            btn_collect.off("click");
            btn_collect.getComponent(cc.Button).interactable = true;
            let self = this;
            let clickFunc = async()=>{
                Global.SlotsSoundMgr.playEffect("click1");
                btn_collect.getComponent(cc.Button).interactable = false;
                if(Global.FormatCommaNumToNum(lbl.getComponent(cc.Label).string) != wincoin){
                    lbl.stopAllActions();
                    lbl.getComponent(cc.Label).string = Global.FormatNumToComma(wincoin);
                    await cc.vv.gameData.awaitTime(0.3);
                }

                cc.tween(self._node_end_free).to(0.5, {scale:0}, {easing:"backIn"}).start();

                await cc.vv.gameData.awaitTime(0.5);
                self._node_popup.active = false;
                self._node_end_free.active = false;
                success();
            };
            cc.vv.gameData.checkAutoPlay(btn_collect, clickFunc);
            btn_collect.on("click", async()=>{
                btn_collect.stopAllActions();
                clickFunc();
            })
        })
    },

    // 收集满触发免费
    playTriSuperFreeAnim(freeCnt, curPage){
        return new Promise(async(success, failed)=>{
            Global.SlotsSoundMgr.playEffect("normal_dialog_show1");
            this._node_popup.active = true;
            this._node_tri_superFree.active = true;
            this._node_tri_superFree.setScale(0);
            cc.tween(this._node_tri_superFree).to(0.5, {scale:1}, {easing:"backOut"}).start();


            let claw_atlas = cc.vv.gameData.GetAtlasByName("claw_store");
            cc.find("lbl_cnt", this._node_tri_superFree).getComponent(cc.Label).string = freeCnt;
            cc.find("spr_type", this._node_tri_superFree).getComponent(cc.Sprite).spriteFrame = claw_atlas.getSpriteFrame(cc.js.formatStr("theme128_gouwu_mingzi_%s",curPage));
            cc.find("spr_type/spr", this._node_tri_superFree).getComponent(cc.Sprite).spriteFrame = claw_atlas.getSpriteFrame(cc.js.formatStr("theme128_gouwu_mingzi_%s_0",curPage));

            await cc.vv.gameData.awaitTime(0.5);
            let btn_start = cc.find("bg_btn/btn_start", this._node_tri_superFree);
            btn_start.off("click");
            btn_start.getComponent(cc.Button).interactable = true;
            let self = this;
            let clickFunc = async()=>{
                Global.SlotsSoundMgr.playEffect("click1");
                btn_start.getComponent(cc.Button).interactable = false;
                cc.tween(self._node_tri_superFree).to(0.5, {scale:0}, {easing:"backIn"}).start();

                await cc.vv.gameData.awaitTime(0.5);
                self._node_popup.active = false;
                self._node_tri_superFree.active = false;
                success();
            };
            cc.vv.gameData.checkAutoPlay(btn_start, clickFunc);
            btn_start.on("click", async()=>{
                btn_start.stopAllActions();
                clickFunc();
            })
        })
    },

    // 商店解锁新的一页
    playUnlockPageAnim(freeCnt, curPage){
        return new Promise(async(success, failed)=>{
            Global.SlotsSoundMgr.playEffect("normal_dialog_show3");
            this._node_popup.active = true;
            this._node_unlock_page.active = true;
            this._node_unlock_page.setScale(0);
            cc.tween(this._node_unlock_page).to(0.5, {scale:1}, {easing:"backOut"}).start();

            let node_normal = cc.find("node_normal", this._node_unlock_page);
            let node_all = cc.find("node_all", this._node_unlock_page);
            node_normal.active = curPage < 4;
            node_all.active = curPage == 4;
            // if(curPage < 4){
            //     let dialog_atlas = cc.vv.gameData.GetAtlasByName("dialog");
                // cc.find("node_normal/spr_type/spr", this._node_unlock_page).getComponent(cc.Sprite).spriteFrame = dialog_atlas.getSpriteFrame(cc.js.formatStr("theme128_popup_shouji_1_%s",curPage+3));
            // }

            await cc.vv.gameData.awaitTime(0.5);
            let btn_start = cc.find("bg_btn/btn_start", this._node_unlock_page);
            btn_start.off("click");
            btn_start.getComponent(cc.Button).interactable = true;
            let self = this;
            let clickFunc = async()=>{
                Global.SlotsSoundMgr.playEffect("click1");
                btn_start.getComponent(cc.Button).interactable = false;
                cc.tween(self._node_unlock_page).to(0.5, {scale:0}, {easing:"backIn"}).start();

                await cc.vv.gameData.awaitTime(0.5);
                self._node_popup.active = false;
                self._node_unlock_page.active = false;
                success();
            };
            cc.vv.gameData.checkAutoPlay(btn_start, clickFunc);
            btn_start.on("click", async()=>{
                btn_start.stopAllActions();
                clickFunc();
            })
        })
    },

    // 再次触发bonus
    playBonusAgainAnim(){
        return new Promise(async(success, failed)=>{
            Global.SlotsSoundMgr.playEffect("normal_dialog_show5");
            this._node_popup.active = true;
            this._node_tri_bonus_again.active = true;
            this._node_tri_bonus_again.setScale(0);
            cc.tween(this._node_tri_bonus_again).to(0.5, {scale:1}, {easing:"backOut"}).start();

            await cc.vv.gameData.awaitTime(0.5);
            let btn_start = cc.find("btn_start", this._node_tri_bonus_again);
            btn_start.off("click");
            btn_start.getComponent(cc.Button).interactable = true;
            let self = this;
            let clickFunc = async()=>{
                Global.SlotsSoundMgr.playEffect("click1");
                btn_start.getComponent(cc.Button).interactable = false;
                cc.tween(self._node_tri_bonus_again).to(0.5, {scale:0}, {easing:"backIn"}).start();

                await cc.vv.gameData.awaitTime(0.5);
                self._node_popup.active = false;
                self._node_tri_bonus_again.active = false;
                success();
            };
            cc.vv.gameData.checkAutoPlay(btn_start, clickFunc);
            btn_start.on("click", async()=>{
                btn_start.stopAllActions();
                clickFunc();
            })
        })
    },

    // 色子
    playQPAnim1(){
        Global.SlotsSoundMgr.playEffect("transition1");

        let self = this;
        this._node_qp.active = true;
        this._qieping_1.active = true;
        this._qieping_1.getComponent(sp.Skeleton).setAnimation(0,"animation", false);
        this._qieping_1.getComponent(sp.Skeleton).setCompleteListener(()=>{
            self._node_qp.active = false;
            self._qieping_1.active = false;
        })
    },

    // 元宝
    playQPAnim2(){
        Global.SlotsSoundMgr.playEffect("transition2");

        let self = this;
        this._node_qp.active = true;
        this._qieping_2.active = true;
        this._qieping_2.getComponent(sp.Skeleton).setAnimation(0,"animation", false);
        this._qieping_2.getComponent(sp.Skeleton).setCompleteListener(()=>{
            self._node_qp.active = false;
            self._qieping_2.active = false;
        })
    },

    playQPAnim3(){
        Global.SlotsSoundMgr.playEffect("transition2");

        let self = this;
        this._node_qp.active = true;
        this._qieping_3.active = true;
        this._qieping_3.getComponent(sp.Skeleton).setAnimation(0,"skill", false);
        this._qieping_3.getComponent(sp.Skeleton).setCompleteListener(()=>{
            self._node_qp.active = false;
            self._qieping_3.active = false;
        })
    },

    // update (dt) {},
});
