
cc.Class({
    extends: require('LMSlots_Slots_Base'),

    properties: {
        _wildList:[],
    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },


    //初始化
    Init:function(type){
        this._slotsType = type;
        this._topScript = cc.vv.gameData.GetTopScript()
        this._bottomScript = cc.vv.gameData.GetBottomScript()

        this._cfg = cc.vv.gameData.getGameCfg()
        this._col = 5
        this._row = 3

        this._topAniNode = cc.find("top_ani",this.node)
        this.createReels(this._col,this._row, type)

        this.initWildSpine();

        // this._bottomScript.ShowBtnsByState("idle")

        // this.RegisterEvent()

        //断线重连的显示
        // this.ReconnectShow()

        //初始化奖池
        // this.CheckJoopLock()
    },

    //创建卷轴
    createReels:function(col,row,type){
        for (let i = 0; i < col; i++) {
            let node = cc.find("reels/reel" + (i+1),this.node)
            let scp = node.addComponent("Alexander_FreeReel")
            scp.Init(i,row,this._topAniNode)
            scp.setSlotType(type);
            this._reels.push(scp)

        }
    },

    // 初始化卷轴数据
    async initSlotsData(){
        this._addRow = cc.vv.gameData.getFreeAddRow();
        this._wildCols = cc.vv.gameData.getFreeWildCols();

        let hisRow = this._row;
        this._row = this._addRow ? 4 : 3;
        // cc.log("this._addRow:",this._addRow, "  hisRow:",hisRow, "this._row:", this._row);
        if(this._addRow && hisRow == 3){ // 需要增加卷轴
            this._reels.forEach((reel)=>{
                reel.AddCount(1,0.01);
            });
            // this._row = 4;

            // this.addSlotsSize(true)
        }
        else if(!this._addRow && hisRow == 4){   // 需要回收卷轴
            // this._row = 3;
            this._reels.forEach((reel)=>{
                reel.StartRecycleSymbol(0.01,this._row);
            });

            // this.addSlotsSize(false)
        }
        // await cc.vv.gameData.awaitTime(0);
        this.addSlotsSize(this._addRow);

        this.initAllSymbol();
        this.hideWildSpine();
        this.showWildSpine();
        // await cc.vv.gameData.awaitTime(0);
    },

    // 是否增加卷轴大小
    addSlotsSize(bAdd){
        this.node.height = this._row * this._cfg.symbolSize.height;
        // let pic = bAdd ? "theme128_reel_3" : "theme128_reel_2";
        // let base_altas = cc.vv.gameData.GetAtlasByName("base");
        // for (let i = 1; i <=5; i++){
        //     cc.find("reels_bg/bg"+i, this.node).getComponent(cc.Sprite).spriteFrame = base_altas.getSpriteFrame(pic);
        // }
    },

    // 初始化所有节点，
    initAllSymbol(){
        for (let col = 0; col < this._reels.length; col++) {
            for (let row = 0; row < this._row+1; row++) {
                if(this._reels[col].GetSymbolByRow(row)){
                    this._reels[col].GetSymbolByRow(row).ClearState();
                    this._reels[col].GetSymbolByRow(row).ShowRandomSymbol();
                }
            }
        }
    },

    initWildSpine(){
        for (let i = 1; i <= 5; i++){
            let wild = cc.find(cc.js.formatStr("reels/reel%s/wild", i), this.node);
            wild.active = false;
            this._wildList.push(wild);
        }
    },

    showWildSpine(){
        let wildCols = cc.vv.gameData.getFreeWildCols();
        let addRow = cc.vv.gameData.getFreeAddRow();

        for (let i = 0; i < wildCols.length; i++){
            let idx = wildCols[i];

            this._wildList[idx-1].active = true;
            let animName = addRow ? "animation4_1" : "animation3_1"
            this._wildList[idx-1].getComponent(sp.Skeleton).setAnimation(0, animName, true);
        }
    },

    hideWildSpine(){
        for (let i = 0; i < this._wildList.length; i++){
            this._wildList[i].active = false;
        }
    },

    StartMove(){
        this._super();
        this.showWildSpine();
    },

    onMsgSpine:function(data){
        this._gameInfo = data
        let cards = data.cards
        this.SetSlotsResult(cards)
    },

    OnSpinEnd(){
        this.ShowWinTrace()
    },

    ShowWinTrace(){
        let allWinIdx = []

        //中奖位置
        for(let i = 0; i < this._gameInfo.zjLuXian.length; i++){
            let item = this._gameInfo.zjLuXian[i]
            for(let idx = 0; idx < item.indexs.length; idx++){
                allWinIdx[item.indexs[idx]] = 1
            }
        }
        if(this._gameInfo.scatterZJLuXian && this._gameInfo.scatterZJLuXian.indexs){
            for(let i = 0; i < this._gameInfo.scatterZJLuXian.indexs.length; i++){
                let val = this._gameInfo.scatterZJLuXian.indexs[i]
                allWinIdx[val] = 1
            }
        }

        let wildCols = cc.vv.gameData.getFreeWildCols();
        let addRow = cc.vv.gameData.getFreeAddRow();
        let playWild = [];
        //总
        for (const key in allWinIdx) {
            let idx = Number(key)
            if(wildCols.includes((idx-1)%5 + 1)){
                playWild.push((idx-1)%5)
            } else {
                let symbol = this.GetSymbolByIdx(Number(key))
                if(symbol){
                    symbol.playWinAnimation()
                    symbol.ShowKuang()
                }
            }
        }
        for (let i = 0;i < playWild.length; i++){
            let animName = addRow ? "animation4" : "animation3"
            this._wildList[playWild[i]].getComponent(sp.Skeleton).setAnimation(0,animName,true);
        }
    },

    //每列停止时间间隔 = 每列的停止间隔 + 每列的回弹时间
    //reelIdx:0开始
    GetReelStopInter:function(reelIdx){
        let nIter = this._cfg.reelStopInter || 0.6
        let col = this._col * this._slotsType;

        return (reelIdx + col)*nIter;
    },

    //如果收到结果不需要里面进入停止节奏，可通过重写此接口来实现自己控制
    //默认是收到结果就停止
    CanStopSlot(){
        return this._gameInfo != null
    },

    // update (dt) {},
});
