
cc.Class({
    extends: cc.Component,

    properties: {
        _rtype: 3,
    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start() {

    },

    Init() {
        this._rtype = 3;    // 51协议rtype字段

        this._spine_character = cc.find("safe_node/spine_character", this.node);
        this._bonus_spins = cc.find("safe_node/slots/node_spins", this.node);
        this._node_winner = cc.find("safe_node/slots/node_winner", this.node);
        this._bonus_spins.active = false;
        this._node_winner.active = false;

        this._spine_bonus_again = cc.find("safe_node/slots/spine_bonus_again", this.node);
        this._spine_bonus_again.active = false;

        //------
        // this.playWin();
    },

    onEnable() {
        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvSubGameAction, this);
    },

    onDisable() {
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvSubGameAction, false, this);
    },

    enterBonusGame() {
        return new Promise(async (success, failed) => {

            Global.SlotsSoundMgr.playBgm("bonus_bgm");

            this.initBonusGame();
            await cc.vv.gameData.awaitTime(2);

            this.bonusStartMove();

            this._bonusSuccess = success;
        })
    },

    async endBonusGame() {
        Global.SlotsSoundMgr.playEffect("bonus_end");
        cc.tween(this._bonus_spins).to(0.5, { opacity: 0 }).start()
        await cc.vv.gameData.awaitTime(0.5);
        this._bonus_spins.active = false;
        this._bonus_spins.opacity = 255;

        cc.tween(this._spine_character).to(0.5, { opacity: 0 }).start()

        this._node_winner.active = true;
        this._node_winner.opacity = 0;
        cc.find("lbl", this._node_winner).getComponent(cc.Label).string = "";
        cc.find("spine_light", this._node_winner).active = false;
        cc.find("spine_win", this._node_winner).active = false;
        cc.tween(this._node_winner).to(0.5, { opacity: 255 }).start();

        await cc.vv.gameData.awaitTime(0.5);
        await this.playCompleteAnim();

        if (this._retriggered) {      // again
            Global.SlotsSoundMgr.playEffect("playitagain");
            this._spine_bonus_again.active = true;
            this._spine_bonus_again.getComponent(sp.Skeleton).setAnimation(0, "animation2", false);

            await cc.vv.gameData.awaitTime(0.5);
            await cc.vv.gameData.getPopupScript().playBonusAgainAnim();

            cc.vv.gameData.setEpicInfo(this._newEpicInfo);

            cc.vv.gameData.setBonusIdxs(this._newEpicInfo.bonusIdxs);
            cc.vv.gameData.setBonusItems(this._newEpicInfo.bonusItems);

            this._node_winner.active = false;
            this._spine_character.opacity = 255;
            cc.vv.gameData.GetSlotsScript().initBonusSymbol();
            // await this.enterBonusGame();

            this.initBonusGame();
            this.bonusStartMove();

            return
        }


        // 显示底部赢钱
        let nWin = this._winCoin
        let nTotal = this._winCoin
        cc.vv.gameData.AddCoin(this._winCoin);
        await new Promise((success, failed) => {
            cc.vv.gameData.GetSlotsScript().ShowBottomWin(nWin, nTotal, true, success)
        });

        cc.find("spine_win", this._node_winner).active = false;
        this._node_winner.active = false;

        if (this._bonusSuccess) {
            this._bonusSuccess();
            this._bonusSuccess = null;
            Global.SlotsSoundMgr.stopBgm();
        }
    },


    // 开始bonus游戏
    bonusStartMove() {
        this._restCnt -= 1;
        this.showBonusSpins(this._restCnt, false);

        cc.vv.gameData.GetSlotsScript().setBonusCanStop(false);
        cc.vv.gameData.GetSlotsScript().StartMove(this._bonusIdxs);

        this.onSendSeq();
    },

    onSendSeq: function () {
        let req = { c: MsgId.SLOT_SUBGAME_DATA };
        req.gameid = cc.vv.gameData.getGameId()
        req.data = {
            rtype: this._rtype
        }
        cc.vv.NetManager.send(req, true);
    },

    onRcvSubGameAction(msg) {
        let data = msg.data;
        if (msg.code === 200 && data && data.rtype == this._rtype) {
            cc.vv.gameData.GetSlotsScript().setBonusCanStop(true);

            if (data) {
                this._isBonusEnd = data.isEnd;
                // if(data.epicInfo){
                this._bonusIdxs = data.epicInfo.bonusIdxs;
                this._bonusItems = data.epicInfo.bonusItems;
                this._retriggered = data.epicInfo.retriggered;
                this._winCoin = data.epicInfo.winCoin;
                // } else {
                //     this._bonusIdxs = data.bonusIdxs;
                //     this._bonusItems = data.bonusItems;
                // }

                this._restCnt = data.epicInfo.restCnt;

                this._newEpicInfo = data.newEpicInfo;

                cc.vv.gameData.setBonusIdxs(this._bonusIdxs);
                cc.vv.gameData.setBonusItems(this._bonusItems);


                let cards = this.getResultCard();
                cc.vv.gameData.GetSlotsScript().SetSlotsResult(cards);
            }
        }
    },

    // 设置旋转结果
    getResultCard() {
        let cfg = cc.vv.gameData.getGameCfg()
        let cards = [];
        for (let i = 1; i <= 20; i++) {
            if (this._bonusIdxs.includes(i)) {
                cards.push(3)
            } else {
                let randIdx = Global.random(1, cfg.randomSymbols.length)
                let randVal = cfg.randomSymbols[randIdx - 1]
                cards.push(randVal)
            }
        }
        return cards;
    },

    // 旋转结束
    async onBonusSpinEnd() {
        if (this._isBonusEnd) {
            this.endBonusGame();

        } else {
            this.showBonusSpins(this._restCnt, false);

            await cc.vv.gameData.awaitTime(2);

            this.bonusStartMove();
        }
    },

    // bonus轮数
    showBonusSpins(rest, bInit) {
        if (rest === false) {
            this._bonus_spins.active = false
        } else {
            this._bonus_spins.active = true;
            this._bonus_spins.opacity = 255;

            let lblList = ["LAST SPIN", "1 SPIN REMAINING", "2 SPINS REMAINING", "3 SPINS REMAINING"];
            cc.find("lbl", this._bonus_spins).getComponent(cc.Label).string = lblList[rest];

            let sp_bomb = cc.find("spine_bomb", this._bonus_spins);
            if (bInit) {
                sp_bomb.active = false;
            } else if (rest == 3) {
                Global.SlotsSoundMgr.playEffect("num");
                sp_bomb.active = true;
                sp_bomb.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
            }
        }
    },

    // 飞金币动画
    async playCompleteAnim() {

        return new Promise(async (success, failed) => {

            let idxs = Global.copy(this._bonusIdxs)
            idxs.sort(function (a, b) {
                return a / 5 - b / 5
            }).sort(function (a, b) {
                return (a - 1) % 5 - (b - 1) % 5
            });

            // cc.log(1);

            let sp_win = cc.find("spine_win", this._node_winner)
            sp_win.active = true;

            let allCoin = this._curCoin;
            let lbl = cc.find("lbl", this._node_winner);
            let spine_light = cc.find("spine_light", this._node_winner);

            for (let i = 0; i < idxs.length; i++) {
                let idx = idxs[i];
                let data = this._bonusItems[this._bonusIdxs.indexOf(idx)];
                if (data.again) {

                } else {
                    Global.SlotsSoundMgr.playEffect("collect");

                    let symbol = cc.vv.gameData.GetSlotsScript().GetSymbolByIdx(idx);
                    let sPos = this._node_winner.convertToNodeSpaceAR(symbol.node.convertToWorldSpaceAR(cc.v2(0, 0)));
                    sp_win.position = sPos;
                    sp_win.angle = this.getRotationAngle(idx);
                    sp_win.scale = this.getScaleMul(idx);
                    sp_win.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
                    symbol.playBonusCollAnim();

                    await cc.vv.gameData.awaitTime(0.5);

                    let addCoin;
                    if (data.coin) {
                        addCoin = data.coin
                    } else if (data.jackpot) {
                        addCoin = data.jackpot.value;
                    }
                    if (addCoin > 0) {
                        allCoin += addCoin

                        lbl.getComponent(cc.Label).string = Global.FormatNumToComma(allCoin);
                        spine_light.active = true;
                        spine_light.getComponent(sp.Skeleton).setAnimation(0, "animation", false);

                        cc.vv.gameData.GetBottomScript().SetWin(allCoin);
                        await cc.vv.gameData.awaitTime(0.3);
                    }
                }
            }

            success()
        });
    },

    initBonusGame() {
        let epicInfo = cc.vv.gameData.getEpicInfo();
        this._bonusIdxs = epicInfo.bonusIdxs;
        this._bonusItems = epicInfo.bonusItems;
        this._currStep = epicInfo.currStep;
        this._restCnt = epicInfo.restCnt;
        this._retriggered = epicInfo.retriggered;
        this._curCoin = epicInfo.winCoin;

        this.showBonusSpins(this._restCnt, true);
        cc.vv.gameData.GetBottomScript().SetWin(this._curCoin);
    },

    //获取旋转角度
    getRotationAngle(col) {
        let list = [-45, -27, 0, 27, 45, -35, -20, 0, 20, 35, -29, -15, 0, 15, 29, -24, -13, 0, 13, 24]
        return list[col - 1];
    },

    // 获取缩放比例
    getScaleMul(col) {
        let list = [0.7, 0.6, 0.5, 0.6, 0.7, 0.9, 0.8, 0.7, 0.8, 0.9, 1.1, 1, 0.9, 1, 1.1, 1.2, 1.1, 1.0, 1.1, 1.2]
        return list[col - 1];
    },

    // update (dt) {},
});
