
cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    // 清除所有状态
    ClearState(){
        this.showPaw();
        this.setAnimationToTop(false)
        this.ShowKuang(false)
        this.stopWinTweenAction()
        this.node.zIndex = 50 - this._symbolIdx  + this._reelIdx*10;
    },

    //显示symbole
    //id:物品id
    //data:额外传递的数据
    ShowById:function(id,data){
        this._super(id, data)


        this.hideAllIcon();
        if(id === 3 && data){
            if(data.coin){
                this.setCoin(data.coin)
            } else if(data.jackpot){
                this.showJackPotNode(data.jackpot.id)
            } else if(data.again){
                this.showBonusAgain();
            }
        }

        if(cc.vv.gameData.isBonusGame()){
            this.setMaskVisible(true);
        } else {
            this.setMaskVisible(false);
        }
    },

    showJackPotNode(jpId){
        if(this._showNode){
            this._showNode.active = false
        }
        let cfg = cc.vv.gameData.getGameCfg()
        let id = this._id;
        if(jpId === 1 && cfg.symbol[id].mini_node){
            this._showNode = cc.find(cfg.symbol[id].mini_node,this.node)
        } else if(jpId === 2 && cfg.symbol[id].minor_node){
            this._showNode = cc.find(cfg.symbol[id].minor_node,this.node)
        } else if(jpId === 3 && cfg.symbol[id].major_node){
            this._showNode = cc.find(cfg.symbol[id].major_node,this.node)
        }
        this._showNode.active = true
    },

    showBonusAgain(){
        if(this._showNode){
            this._showNode.active = false
        }
        let cfg = cc.vv.gameData.getGameCfg()
        let id = this._id;
        if(cfg.symbol[id].again_node){
            this._showNode = cc.find(cfg.symbol[id].again_node,this.node)
        }
        this._showNode.active = true
    },

    // 隐藏所有特殊图标
    hideAllIcon(){
        this.setCoin();
        this.showPaw();
    },

    setCoin(num){
        let lbl_coin = cc.find("lbl_coin", this.node);
        if(num){
            let font = null;
            let nVal = cc.vv.gameData.GetTotalBet();
            if(num < 5*nVal){
                font = cc.vv.gameData.GetFontByName("theme128_font_b_2");
            } else {
                font = cc.vv.gameData.GetFontByName("theme128_font_b_1");
            }

            lbl_coin.active = true;
            lbl_coin.getComponent(cc.Label).font = font;
            lbl_coin.getComponent(cc.Label).string = Global.formatNumShort(num,0);
        } else {
            lbl_coin.active = false;
            lbl_coin.getComponent(cc.Label).string = "";
        }
    },

    showPaw(animType){
        let paw = cc.find("paw", this.node);
        if(animType){
            paw.active = true;
            paw.getComponent(sp.Skeleton).setAnimation(0, "animation"+animType, false);
        }else {
            paw.active = false;
        }
    },

    getPaw(){
        return cc.find("paw", this.node);
    },

    getPawAnimName(cnt){
        let name;
        if(cnt === 5){
            name = "animation1";
        } else if (cnt === 10){
            name = "animation2";
        } else if (cnt === 15){
            name = "animation3";
        } else if (cnt === 20){
            name = "animation4";
        } else if (cnt === 25){
            name = "animation5";
        } else if (cnt === 30){
            name = "animation6";
        } else if (cnt === 35){
            name = "animation7";
        } else if (cnt === 40){
            name = "animation8";
        } else if (cnt === 50){
            name = "animation9";
        }

        return name;
    },

    //触发动画
    //触发了才播放的。比如已经3个scatter已经触发了免费。这个和中奖的还不一样
    playTriggerAnimation(){
        let isPlay = false
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].trigger_ani){
            this._state = "trigger";
            if(this._showNode){
                this._showNode.active = false
            }
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            let topShowNode = cc.find(cfg.symbol[id].win_node,aniNode)
            topShowNode.active = true
            if(cfg.symbol[id].trigger_ani.name != ""){
                aniNode.zIndex = cfg.symbol[id].trigger_ani.zIndex - this._symbolIdx + this._reelIdx*10;
                isPlay = true
                let nodeSp = topShowNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,cfg.symbol[id].trigger_ani.name,true)
                }
            }
        }
        return isPlay
    },

    playStopAnimation(){
        let id = this._id;
        if(id == 3){
            this._showNode.stopAllActions()
            //记录原始缩放
            let nScale = this._showNode.scale
            this._showNodeOrgScale = nScale

            cc.tween(this._showNode)
                .to(0.35,{scale:nScale+0.2})
                .to(0.35,{scale:nScale})
                .start()
        }else {
            this._super();
        }
    },

    // bonus待机动画
    playBonusIdleAnim(){
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(id == 3 && cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].idle_ani){
            if(this._showNode){
                this._showNode.active = false
            }
            this._showNode = cc.find(cfg.symbol[id].win_node,this.node)
            this._showNode.active = true

            let ani = cfg.symbol[id].idle_ani
            let animName = ani.name
            if(this._data.coin){
            } else if(this._data.jackpot){
                if(this._data.jackpot.id == 1){
                    animName = ani.mini_name
                } else if(this._data.jackpot.id == 2){
                    animName = ani.minor_name
                } else if(this._data.jackpot.id == 3){
                    animName = ani.major_name
                }
            }else if(this._data.again){
                animName = ani.again_name
            }


            if(animName != ""){
                this.node.zIndex = cfg.symbol[id].idle_ani.zIndex - this._symbolIdx  + this._reelIdx*10;
                let nodeSp = this._showNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,animName,true)
                }
            }
        }
    },

    // bonus收集动画
    playBonusCollAnim(){
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(id == 3 && cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].coll_ani){
            if(this._showNode){
                this._showNode.active = false
            }
            this._showNode = cc.find(cfg.symbol[id].win_node,this.node)
            this._showNode.active = true

            let ani = cfg.symbol[id].coll_ani
            let animName = ani.name
            if(this._data.coin){
            } else if(this._data.jackpot){
                if(this._data.jackpot.id == 1){
                    animName = ani.mini_name
                } else if(this._data.jackpot.id == 2){
                    animName = ani.minor_name
                } else if(this._data.jackpot.id == 3){
                    animName = ani.major_name
                }
            }else if(this._data.again) {
                animName = ani.again_name
            }

            if(animName != ""){
                this.node.zIndex = cfg.symbol[id].coll_ani.zIndex - this._symbolIdx  + this._reelIdx*10;
                let nodeSp = this._showNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,animName,false)
                }
            }
        }
    },

    StartMove() {
        this._super();

        if(cc.vv.gameData.isBonusGame()){
            this.setMaskVisible(true);
        } else {
            this.setMaskVisible(false);
        }

    },

    setMaskVisible(isMask) {
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[this._id] && cfg.symbol[this._id].node){
            let showNode = cc.find(cfg.symbol[this._id].node,this.node)
            if (isMask && cfg.symbol[this._id].isMask) {
                showNode.color = new cc.Color(100, 100, 100);
            }
            else {
                showNode.color = cc.Color.WHITE;
            }
        }
    },

    // update (dt) {},
});
