
cc.Class({
    extends: cc.Component,

    properties: {
        _slotsNodeList : [],
        _slotsScpList : [],

    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    Init(){
        this._node_free = cc.find("safe_node/node_free", this.node);
        this._node_free.active = false;

        this._node_slots = cc.find("slots", this._node_free);
        for (let i = 1; i <= 4; i++){
            let slot = cc.find("slots"+i, this._node_slots);
            let scp = slot.addComponent("Alexander_FreeSlots");
            scp.Init(i);

            this._slotsNodeList.push(slot);
            this._slotsScpList.push(scp);
        }
    },

    // 初始显示slots  isTri-触发
    initShowSlotsData(isTri){
        return new Promise(async (success, failed)=>{
            Global.SlotsSoundMgr.playBgm("free_bgm");

            cc.vv.gameData.setIsFreeGame(true)
            this._node_free.active = true;
            this.showNormalSlots(false);

            this._slotsCnt = cc.vv.gameData.getFreeSlotsCnt();
            this._addRow = cc.vv.gameData.getFreeAddRow();
            this._wildCols = cc.vv.gameData.getFreeWildCols();

            this.setSlotsScale();
            this.showWildSpine();
            // await cc.vv.gameData.awaitTime(0);

            for (let i = 0; i < this._slotsNodeList.length; i++){
                if(i < this._slotsCnt){
                    this._slotsNodeList[i].active = true;
                    this._slotsScpList[i].initSlotsData();
                } else {
                    this._slotsNodeList[i].active = false;
                }
            }

            if(isTri){
                await cc.vv.gameData.awaitTime(0.5);
                cc.vv.gameData.getMapScript().hideMapNode();
            }

            // if(isTri){
                cc.vv.gameData.GetSlotsScript().CanDoNextRound();
            // }

            this._freeSuccess = success;
        })
    },

    // 结束免费游戏
    async endFreeGame(){
        await cc.vv.gameData.awaitTime(1);
        await cc.vv.gameData.getPopupScript().playEndFreeAnim();

        cc.vv.gameData.getPopupScript().playQPAnim3();
        await cc.vv.gameData.awaitTime(0.7);
        this._node_free.active = false;
        this.showNormalSlots(true);
        cc.vv.gameData.GetBottomScript().ShowFreeModel(false);
        this.hideWildSpine();

        await cc.vv.gameData.awaitTime(2)
        await new Promise((success)=>{
            // let nWin = cc.vv.gameData.GetGameWin()
            let nTotal = cc.vv.gameData.getFreeWinCoin()
            cc.vv.gameData.GetSlotsScript().ShowBottomWin(nTotal,nTotal,true,()=>{
                success();
            });
        });

        cc.vv.gameData.setIsFreeGame(false);
        Global.SlotsSoundMgr.stopBgm();
        if(this._freeSuccess){
            this._freeSuccess();
            this._freeSuccess = null;
        }

        // cc.vv.gameData.GetBottomScript().CanDoNextRound();
    },


    // 设置slots大小和位置
    setSlotsScale(){
        let scaleList = [1,0.9,0.53,0.53];
        this._node_slots.setScale(scaleList[this._slotsCnt-1]);
        this._node_slots.getComponent(cc.Widget).updateAlignment();

        let cfg = cc.vv.gameData.getGameCfg();
        let row = this._addRow ? 4 : 3;
        let c_X = 0;
        let r_X = this._slotsNodeList[0].width/2 + 16;
        let b_Y = cfg.symbolSize.height * row / 2;
        let t_Y = 3 * b_Y + 30;

        // 1个3行slots 和 3或4个slots
        if((this._slotsCnt == 1 && !this._addRow) || this._slotsCnt > 2){
            t_Y += cfg.symbolSize.height;
            b_Y += cfg.symbolSize.height;
        }

        if(this._slotsCnt == 1) {    // 1个
            this._slotsNodeList[0].position = cc.v2(c_X,b_Y);
        } else if(this._slotsCnt == 2) {    // 2个
            this._slotsNodeList[0].position = cc.v2(c_X,t_Y);
            this._slotsNodeList[1].position = cc.v2(c_X,b_Y);
        } else if(this._slotsCnt == 3) {    // 3个
            this._slotsNodeList[0].position = cc.v2(c_X,t_Y);
            this._slotsNodeList[1].position = cc.v2(-r_X,b_Y);
            this._slotsNodeList[2].position = cc.v2(r_X,b_Y);
        } else if(this._slotsCnt == 4) {    // 4个
            this._slotsNodeList[0].position = cc.v2(-r_X,t_Y);
            this._slotsNodeList[1].position = cc.v2(r_X,t_Y);
            this._slotsNodeList[2].position = cc.v2(-r_X,b_Y);
            this._slotsNodeList[3].position = cc.v2(r_X,b_Y);
        }

    },

    // 设置wild
    showWildSpine(){
        for (let i = 0; i < this._slotsNodeList.length; i++) {
            if (i < this._slotsCnt) {
                this._slotsScpList[i].showWildSpine();
            }
        }
    },

    hideWildSpine(){
        for (let i = 0; i < this._slotsNodeList.length; i++) {
            if (i < this._slotsCnt) {
                this._slotsScpList[i].hideWildSpine();
            }
        }
    },

    //点击旋转按钮调用
    StartMove(){
        for (let i = 0; i < this._slotsNodeList.length; i++) {
            if (i < this._slotsCnt) {
                this._slotsScpList[i].StartMove();
            }
        }
    },

    //点击停止按钮调用
    StopMove:function(){
        for (let i = 0; i < this._slotsNodeList.length; i++) {
            if (i < this._slotsCnt) {
                this._slotsScpList[i].StopMove();
            }
        }
    },

    //收到旋转结果
    onMsgSpine(msg){
        cc.log(msg);
        this._gameInfo = msg;

        let freeGameSlots = msg.freeGameSlots;
        for (let i = 0; i < this._slotsNodeList.length; i++) {
            if (i < this._slotsCnt) {
                this._slotsScpList[i].onMsgSpine(freeGameSlots[i]);
            }
        }
    },

    async OnSpinEnd(){
        for (let i = 0; i < this._slotsNodeList.length; i++) {
            if (i < this._slotsCnt) {
                this._slotsScpList[i].OnSpinEnd();
            }
        }

        // 显示底部赢钱
        let win = this._gameInfo.wincoin;
        let nTotal = cc.vv.gameData.getFreeWinCoin();
        await new Promise((success, failed)=>{

            cc.vv.gameData.GetSlotsScript().ShowBottomWin(win,nTotal,true,function () {
                success()
            })
        });

        if(cc.vv.gameData.GetTotalFree()>0 && cc.vv.gameData.GetFreeTime()== 0){
            this.endFreeGame();

            return ;
        }


        cc.vv.gameData.GetSlotsScript().CanDoNextRound()
    },

    GetLastStopReelIdx(){
        return this._slotsScpList[this._slotsCnt-1].GetLastStopReelIdx();
    },




    showNormalSlots(bShow){
        cc.find("safe_node/slots", this.node).active = bShow;
        // cc.find("safe_node/spine_character", this.node).active = bShow;
        // cc.find("safe_node/LMSlots_PrizePool_1", this.node).active = bShow;
        // cc.find("safe_node/spr_logo", this.node).active = bShow;
    },
    // update (dt) {},
});
