
// 1-锁 2-窝可点击 3-窝不可点击 4-骨头钱 5-骨头bonus 6-骨头map
let itemType = {
    lock     : 1,
    canClick : 2,
    unClick  : 3,
    coin     : 4,
    bonus    : 5,
    map      : 6,
};

cc.Class({
    extends: cc.Component,

    properties: {
        _rtype:1,

        _itemList:[],

    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    Init(){
        this._btn_entrance = cc.find("safe_node/slots/btn_entrance", this.node);
        this._btn_entrance.off("click");
        Global.btnClickEvent(this._btn_entrance, this.onClickEntranceBtn, this);

        this._node_store = cc.find("safe_node/node_store", this.node);
        this._node_store.active = false;
        this._btn_close = cc.find("layout/btn_close", this._node_store);
        Global.btnClickEvent(this._btn_close, this.onClickCloseBtn, this);

        this._node_items = cc.find("layout/node_items", this._node_store);
        for (let i = 1; i <= 9; i++){
            let item = cc.find("item"+i, this._node_items);
            item.off("click");
            Global.btnClickEvent(item, this.onClickItem, this);
            // this._itemList.push(item);

            this._itemList[i] = {node:item,type:1,data:null};
        }

        this._spine_dianliang = cc.find("layout/spine_dianliang", this._node_store);
        this._spine_dianliang.active = false;

        this._box_tip = cc.find("layout/box_tip", this._node_store);
        this._box_tip.active = false;
        this._spr_tip = cc.find("layout/spr_tip", this._node_store);
        this._spr_tip.active = false;
        let btn_tip = cc.find("layout/btn_tip", this._node_store);
        Global.btnClickEvent(btn_tip, this.clickHelpBtn, this);
        let btn_left = cc.find("layout/btn_left", this._node_store);
        Global.btnClickEvent(btn_left, this.clickLeftBtn, this);
        let btn_right = cc.find("layout/btn_right", this._node_store);
        Global.btnClickEvent(btn_right, this.clickRightBtn, this);

        this._pawStore = cc.vv.gameData.getPawStore();
        this.initEntranceBtn();
        this.updateCurMoney();
    },


    onEnable(){
        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvSubGameAction, this);
    },

    onDisable(){
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvSubGameAction, false, this);
    },

    // 点入口图标
    onClickEntranceBtn(){
        if (!cc.vv.gameData.GetBottomScript().GetSpinBtnState()) return;
        if (cc.vv.gameData.GetAutoModelTime() > 0) return;
        if (cc.vv.gameData.isFreeGame()) return;
        if (cc.vv.gameData.isBonusGame()) return;

        Global.SlotsSoundMgr.playEffect("click");

        this._btn_entrance.getComponent(cc.Button).interactable = false;
        this.openStorePage();
    },

    initEntranceBtn(){
        let spine_fz = cc.find("spine_fz", this._btn_entrance);
        spine_fz.getComponent(sp.Skeleton).setAnimation(0,"animation2", true);

        // let lbl_money = cc.find("lbl_money", this._btn_entrance);
        // lbl_money.getComponent(cc.Label).string = Global.FormatNumToComma(this._pawStore.pawCnt);

        cc.find("node_fly", this._btn_entrance).active = false;
    },

    showEntranceBtn(bShow){
        this._btn_entrance.active = bShow;
    },

    playWinPawAnim(){
        let spine_fz = cc.find("spine_fz", this._btn_entrance);
        spine_fz.getComponent(sp.Skeleton).setAnimation(0,"animation1", false);
        spine_fz.getComponent(sp.Skeleton).addAnimation(0,"animation2", true);

        this.updateCurMoney();
    },

    updateCurMoney(){
        this._pawStore = cc.vv.gameData.getPawStore();

        let lbl_money = cc.find("lbl_money", this._btn_entrance);
        lbl_money.getComponent(cc.Label).string = Global.FormatNumToComma(this._pawStore.pawCnt);

        let lbl = cc.find("layout/money_bg/lbl", this._node_store);
        lbl.getComponent(cc.Label).string = Global.FormatNumToComma(this._pawStore.pawCnt);
    },

    // 打开商店页面
    openStorePage(){
        return new Promise(async(success, failed)=> {
            cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_1");

            this._node_store.active = true;
            this._node_store.opacity = 0;
            let layout = cc.find("layout", this._node_store);
            layout.setScale(0);
            cc.tween(this._node_store).to(0.5, {opacity: 255}).start();
            cc.tween(layout).to(0.5, {scale: 1}).start();

            this._pawStore = cc.vv.gameData.getPawStore();
            // this._pageDetails = this._pawStore.pageDetails;
            this._curPage = this._pawStore.unlockPage;
            // this._unlockPage = this._pawStore.unlockPage;
            // this._unlockItems = this._pawStore.unlockItems;


            this.showTitleSpr();
            // this.showCurMoney();
            this.showAllItems();
            this.showPageFooter();
            this.updateCurMoney();

            await cc.vv.gameData.awaitTime(0.5);
            this._canClickItem = true;

            success();
        })
    },

    // 关闭商店页面
    async closeStorePage(){
        return new Promise(async(success, failed)=>{
            let layout = cc.find("layout", this._node_store);
            cc.tween(this._node_store).to(0.5,{opacity:0}).start();
            cc.tween(layout).to(0.5,{scale:0}).start();

            await cc.vv.gameData.awaitTime(0.5);
            this._node_store.active = false;

            success();
        })
    },



    // 标题
    showTitleSpr(){
        let tit_unlock = cc.find("layout/node_tit/tit_unlock", this._node_store);
        let tit_lock = cc.find("layout/node_tit/tit_lock", this._node_store);

        tit_unlock.active = this._curPage <= this._pawStore.unlockPage;
        tit_lock.active = this._curPage > this._pawStore.unlockPage;

        let paw_atlas = cc.vv.gameData.GetAtlasByName("claw_store");
        if(this._curPage <= this._pawStore.unlockPage){  // 解锁
            cc.find("spr_tit", tit_unlock).getComponent(cc.Sprite).spriteFrame = paw_atlas.getSpriteFrame(cc.js.formatStr("theme128_gouwu_mingzi_%s",this._curPage));
            cc.find("spr_tit/spr", tit_unlock).getComponent(cc.Sprite).spriteFrame = paw_atlas.getSpriteFrame(cc.js.formatStr("theme128_gouwu_mingzi_%s_0",this._curPage));
            cc.find("spr_rewards", tit_unlock).getComponent(cc.Sprite).spriteFrame = paw_atlas.getSpriteFrame(cc.js.formatStr("theme128_gouwu_qipan_%s",this._curPage));
        } else {
            cc.find("spr2", tit_lock).getComponent(cc.Sprite).spriteFrame = paw_atlas.getSpriteFrame(cc.js.formatStr("theme128_gouwu_mingzi_%s",this._curPage+3));
        }
    },

    // 所有房子
    showAllItems(){
        let pageData = this._pawStore.unlockItems[this._curPage - 1];
        let pagePrice = this._pawStore.pageDetails[this._curPage - 1].price;

        for(let i = 1; i <= 9; i++){
            let item = this._itemList[i].node;

            let type = this._itemList[i].type;
            let data = this._itemList[i].type;
            if(this._curPage <= this._pawStore.unlockPage){  // 页面解锁
                let itemData = this.getItemData(i, pageData);
                if(itemData){   // 已经打开
                    if(itemData.coin > 0){
                        type = itemType.coin;
                        data = itemData.coin;
                        this.setItemState(item, itemType.coin, itemData.coin);
                    } else if(itemData.epicInfo){
                        type = itemType.bonus;
                        this.setItemState(item, itemType.bonus);
                    } else if(itemData.mapGame){
                        type = itemType.map;
                        this.setItemState(item, itemType.map);
                    }
                }
                else {
                    if(pagePrice <= this._pawStore.pawCnt){ // 钱足够
                        type = itemType.canClick;
                        data = pagePrice;
                        this.setItemState(item, itemType.canClick, pagePrice);
                    } else {    // 钱不够
                        type = itemType.unClick;
                        data = pagePrice;
                        this.setItemState(item, itemType.unClick, pagePrice);
                    }
                }
            }
            else {  // 箱子锁住
                type = itemType.lock;
                data = pagePrice;
                this.setItemState(item, itemType.lock, pagePrice);
            }
            this._itemList[i].type = type;
            this._itemList[i].data = data;
        }
    },

    // 获取单个房子的数据
    getItemData(idx, pageData){
        for (let i = 0; i < pageData.length; i++){
            if(idx == pageData[i].idx){
                return pageData[i]
            }
        }
        return null
    },

    // 设置单个房子的状态  type: 1-锁 2-窝可点击 3-窝不可点击 4-骨头钱 5-骨头bonus 6-骨头map
    setItemState(item, type, data){
        let spine_gw = cc.find("gw", item);
        let money_bg = cc.find("money_bg", item);
        let money_lbl = cc.find("money_bg/lbl", item);
        let spine_gt = cc.find("gt", item);
        let gt_lbl = cc.find("gt/lbl", item);
        let gt_bonus = cc.find("gt/spr_bonus", item);
        let gt_map = cc.find("gt/spr_map", item);
        let spine_change = cc.find("spine_change", item);
        let suo = cc.find("suo", item);

        spine_gw.active = type === itemType.canClick || type === itemType.unClick || type === itemType.lock;
        if(type === itemType.canClick){
            spine_gw.getComponent(sp.Skeleton).setAnimation(0,"animation1",true)
        } else if(type === itemType.unClick || type === itemType.lock){
            spine_gw.getComponent(sp.Skeleton).setAnimation(0,"animation2",true)
        }
        money_bg.active = type === itemType.canClick || type === itemType.unClick || type === itemType.lock;
        if(money_bg.active){
            money_lbl.getComponent(cc.Label).string = Global.FormatNumToComma(data);
        }
        spine_gt.active = type === itemType.coin || type === itemType.bonus || type === itemType.map;
        if(spine_gt.active){
            spine_gt.getComponent(sp.Skeleton).setAnimation(0,"animation2",true)
        }
        gt_lbl.active = type === itemType.coin;
        if(type === itemType.coin && data){
            gt_lbl.getComponent(cc.Label).string = Global.formatNumShort(data,1)
        }
        gt_bonus.active = type === itemType.bonus;
        gt_map.active = type === itemType.map;
        spine_change.active = false;
        suo.active = type === itemType.lock;

    },

    // 房子打开后动画
    setItemResult(idx, data){
        return new Promise(async(success, failed)=>{
            let item = this._itemList[idx].node;

            let spine_gw = cc.find("gw", item);
            let money_bg = cc.find("money_bg", item);
            let money_lbl = cc.find("money_bg/lbl", item);
            let spine_gt = cc.find("gt", item);
            let gt_lbl = cc.find("gt/lbl", item);
            let gt_bonus = cc.find("gt/spr_bonus", item);
            let gt_map = cc.find("gt/spr_map", item);
            let spine_change = cc.find("spine_change", item);
            let suo = cc.find("suo", item);

            spine_change.active = true;
            spine_change.getComponent(sp.Skeleton).setAnimation(0, "animation", false);

            spine_gw.active = false;
            spine_gt.active = true;
            money_bg.active = false;
            spine_gt.getComponent(sp.Skeleton).setAnimation(0,"animation1",false)
            await cc.vv.gameData.awaitTime(0.5)

            let showNode;
            if(data.coin > 0){
                this._itemList[idx].type = itemType.coin;
                gt_lbl.getComponent(cc.Label).string = Global.formatNumShort(data.coin,1);
                showNode = gt_lbl;
            } else if(data.epicInfo){
                this._itemList[idx].type = itemType.bonus;
                showNode = gt_bonus;
            } else if(data.mapGame){
                this._itemList[idx].type = itemType.map;
                showNode = gt_map;
            }

            showNode.active = true;
            showNode.setScale(0)
            cc.tween(showNode).to(0.5, {scale:1}, {easing:"backOut"}).start()
            await cc.vv.gameData.awaitTime(0.5)

            success();
        })

    },


    // 点房子
    onClickItem(event){
        if(!this._canClickItem){
            return
        }

        let idx =  Number(event.node.name.substring("item".length));
        let curType = this._itemList[idx].type;
        if(curType === itemType.lock || curType === itemType.unClick){
            this.playBoxTipAnim(event.node);
        } else if(this._itemList[idx].type === itemType.canClick){
            Global.SlotsSoundMgr.playEffect("show");

            this._canClickItem = false;
            this.onSendSeq(idx);
        }
    },

    onSendSeq:function(idx){
        let req = {c: MsgId.SLOT_SUBGAME_DATA};
        req.gameid = cc.vv.gameData.getGameId()
        req.data = {
            rtype:this._rtype,
            pageId:this._curPage,
            choiceId:idx,
        }
        cc.vv.NetManager.send(req,true);
    },

    onRcvSubGameAction(msg){
        let data  = msg.data;
        if(msg.code === 200 && data && data.rtype == this._rtype){
            this.showClickResult(data);
        }
    },

    // 点击结果
    async showClickResult(data){

        this._pawStore = data.pawStore;
        cc.vv.gameData.setPawStore(this._pawStore);
        this.updateCurMoney();

        let result = data.result;
        let idx = data.choiceId;


        await this.setItemResult(idx, result);
        if(this._pawStore.pageDetails[this._curPage-1].price > this._pawStore.pawCnt){  // 钱不够
            for (let i = 1; i <= 9; i++){
                if(this._itemList[i].type === itemType.canClick){
                    this._itemList[i].type = itemType.unClick;
                    this.setItemState(this._itemList[i].node, itemType.unClick, this._itemList[i].data)
                }
            }
        }

        if(result.coin > 0){    // 赢钱
            cc.vv.gameData.AddCoin(result.coin);
            cc.vv.gameData.GetBottomScript().SetWin(result.coin);
            cc.vv.gameData.GetTopScript().ShowCoin();
        }
        if(result.mapGame || result.epicInfo || result.pageReward){
            await this.closeStorePage();

            if(result.mapGame){  // 赢地图
                cc.vv.gameData.setMapGame(result.mapGame);

                await cc.vv.gameData.getPopupScript().playTriMapAnim();
                cc.vv.gameData.getPopupScript().playQPAnim3();

                await cc.vv.gameData.awaitTime(0.7);
                await cc.vv.gameData.getMapScript().showMapGame();

                // cc.vv.gameData.GetSlotsScript().CanDoNextRound();
            }
            else if(result.epicInfo){ // 赢bonus
                cc.vv.gameData.setEpicInfo(result.epicInfo);
                cc.vv.gameData.setBonusIdxs(result.epicInfo.bonusIdxs)
                cc.vv.gameData.setBonusItems(result.epicInfo.bonusItems)

                await cc.vv.gameData.getPopupScript().playTriBonusAnim();
                cc.vv.gameData.getPopupScript().playQPAnim2();

                await cc.vv.gameData.awaitTime(0.7);
                cc.vv.gameData.GetSlotsScript().showBonusGameView(true);
                cc.vv.gameData.GetSlotsScript().Backup();
                cc.vv.gameData.GetSlotsScript().initAllSymbol();
                cc.vv.gameData.GetSlotsScript().setAllSymbolMask(true);
                cc.vv.gameData.GetBottomScript().SetWin(0);

                // await cc.vv.gameData.awaitTime(2);
                await cc.vv.gameData.getBonusScript().enterBonusGame();

                cc.vv.gameData.getPopupScript().playQPAnim2();
                await cc.vv.gameData.awaitTime(0.7);
                cc.vv.gameData.GetSlotsScript().showBonusGameView(false);
                cc.vv.gameData.GetSlotsScript().Resume();
                cc.vv.gameData.GetSlotsScript().setAllSymbolMask(false);
                await cc.vv.gameData.awaitTime(1);
                cc.vv.gameData.GetTopScript().StopMove();
            }

            if(result.pageReward){  // 集满
                let freeCnt = result.pageReward.freeCnt
                let slotCnt = result.pageReward.slotCnt
                let wildCols = result.pageReward.wildCols
                let extraRow = 1

                cc.vv.gameData.SetTotalFree(freeCnt);
                cc.vv.gameData.SetFreeTime(freeCnt);
                cc.vv.gameData.setFreeAddRow(extraRow);
                cc.vv.gameData.setFreeSlotsCnt(slotCnt);
                cc.vv.gameData.setFreeWildCols(wildCols);

                Global.SlotsSoundMgr.playEffect("collect_finish");
                this._spine_dianliang.active = true;
                this._spine_dianliang.getComponent(sp.Skeleton).setAnimation(0,"animation1", false);

                await this.closeStorePage();

                await cc.vv.gameData.getPopupScript().playTriSuperFreeAnim(freeCnt, this._curPage);
                cc.vv.gameData.getPopupScript().playQPAnim3();

                await cc.vv.gameData.awaitTime(0.7);
                //显示免费次数
                cc.vv.gameData.GetBottomScript().ShowFreeModel(true,0,freeCnt);
                await cc.vv.gameData.getFreeScript().initShowSlotsData(true,true);

                await cc.vv.gameData.getPopupScript().playUnlockPageAnim(freeCnt, this._curPage);
            }
            await this.openStorePage()
        } else {
            // 设置可以再次点击
            this._canClickItem = true;
        }
    },



    onClickCloseBtn(){
        Global.SlotsSoundMgr.playEffect("click1");

        this.closeStorePage();

        this._btn_entrance.getComponent(cc.Button).interactable = true;
        cc.vv.gameData.GetBottomScript().ShowBtnsByState("idle");
    },


    // 箱子提示动画
    playBoxTipAnim(node){
        this._box_tip.stopAllActions();
        if(this._box_tip.active){
            this._box_tip.runAction(cc.sequence(
                cc.scaleTo(this._box_tip.scaleX/2,0,0),
                cc.callFunc(()=>{ this._box_tip.active = false;})
            ))
        } else {
            this._box_tip.position = this._box_tip.parent.convertToNodeSpaceAR(node.convertToWorldSpaceAR(cc.v2(0,0)));
            this._box_tip.active = true;
            this._box_tip.setScale(0);
            this._box_tip.runAction(cc.sequence(
                cc.scaleTo(0.5,1,1),
                cc.delayTime(1),
                cc.scaleTo(0.5,0,0),
                cc.callFunc(()=>{ this._box_tip.active = false;})
            ))
        }
    },

    // 点击问号
    clickHelpBtn(){
        Global.SlotsSoundMgr.playEffect("click1");

        this._spr_tip.stopAllActions();
        if(this._spr_tip.active){
            this._spr_tip.runAction(cc.sequence(
                cc.scaleTo(this._spr_tip.scaleX/2,0,0),
                cc.callFunc(()=>{ this._spr_tip.active = false;})
            ))
        } else {
            this._spr_tip.active = true;
            this._spr_tip.setScale(0);
            this._spr_tip.runAction(cc.sequence(
                cc.scaleTo(0.5,1,1),
                cc.delayTime(1),
                cc.scaleTo(0.5,0,0),
                cc.callFunc(()=>{ this._spr_tip.active = false;})
            ))
        }
    },

    // 左翻页
    async clickLeftBtn(){
        if(!this._canClickItem){
            return
        }
        this._canClickItem = false;
        Global.SlotsSoundMgr.playEffect("click1");

        if(this._curPage<=1){
            this._curPage = 4;
        }else{
            this._curPage--;
        }

        this.refreshDataWithAction(20);
        this.showPageFooter();

        await cc.vv.gameData.awaitTime(1);
        this._canClickItem = true
    },

    // 右翻页
    async clickRightBtn(){
        if(!this._canClickItem){
            return
        }
        this._canClickItem = false;
        Global.SlotsSoundMgr.playEffect("click1");

        if(this._curPage>=4){
            this._curPage = 1;
        }else{
            this._curPage++;
        }


        this.refreshDataWithAction(20);
        this.showPageFooter();

        await cc.vv.gameData.awaitTime(1);
        this._canClickItem = true
    },

    async refreshDataWithAction(deltaX){

        if(deltaX != 0){
            this._node_items.stopAllActions();
            this._node_items.x = 0;
            this._node_items.runAction(cc.sequence(cc.spawn(cc.fadeTo(0.15,63),cc.moveBy(0.15,deltaX,0)),
                cc.spawn(cc.fadeTo(0.15,255),cc.moveBy(0.15,-deltaX,0))));

            let node_tit = cc.find("layout/node_tit", this._node_store);
            node_tit.stopAllActions();
            node_tit.x = 0;
            node_tit.runAction(cc.sequence(cc.spawn(cc.fadeTo(0.15,63),cc.moveBy(0.15,deltaX,0)),
                cc.spawn(cc.fadeTo(0.15,255),cc.moveBy(0.15,-deltaX,0))));

            await cc.vv.gameData.awaitTime(0.15);
            this.showTitleSpr();
        }

        this.showAllItems();
        for(let i=1; i<=9; i++){
            let item = this._itemList[i].node;
            item.setScale(0.1);
            item.stopAllActions();
            item.runAction(cc.scaleTo(0.1*i, 1,1).easing(cc.easeBackOut()))
        }
    },

    // 当前页码
    showPageFooter(){
        for (let i = 1; i <= 4; i++){
            let choosed = cc.find(cc.js.formatStr("layout/choose_bg/choose%s/choosed", i), this._node_store);

            choosed.active = i === this._curPage;
        }
    },

    // update (dt) {},
});
